insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_leisure','leisure','noun','time when you are not working or studying and can relax or enjoy activities','[{"senseId":"leisure_1","meaning":"time when you are not working or studying and can relax or enjoy activities","acceptedParaphrases":["free time","spare time"],"masteryContexts":[{"contextId":"u1_01_leisure_meaning","text":"Many students use their leisure time to play sport or meet friends.","meaning":"time free for enjoyable activities"},{"contextId":"u1_01_leisure_paraphrase","text":"The council built new leisure facilities so residents could exercise and relax after work.","meaning":"recreation time outside normal duties"}],"contextDependentParaphrases":[],"misleadingDistractors":["salary","training","deadline"]}]'::jsonb,'[]'::jsonb,'["leisure time","leisure activity"]'::jsonb,'live'),
('vocab_preference','preference','noun','a greater liking for one option than another','[{"senseId":"preference_1","meaning":"a greater liking for one option than another","acceptedParaphrases":["choice you favour","liking"],"masteryContexts":[{"contextId":"u1_02_preference_meaning","text":"The survey showed that most people have a strong preference for fresh food over tinned food.","meaning":"favouring one option over another"},{"contextId":"u1_02_preference_paraphrase","text":"When I booked the flight, the website asked whether I had a preference for a window or an aisle seat.","meaning":"a stronger choice between alternatives"}],"contextDependentParaphrases":[],"misleadingDistractors":["requirement","permission","result"]}]'::jsonb,'["prefer","preferable"]'::jsonb,'["personal preference","express a preference"]'::jsonb,'live'),
('vocab_avoid','avoid','verb','to stay away from something or prevent it from happening','[{"senseId":"avoid_1","meaning":"to stay away from something or prevent it from happening","acceptedParaphrases":["stay away from","prevent"],"masteryContexts":[{"contextId":"u1_03_avoid_meaning","text":"Try to avoid eating a big meal just before you swim.","meaning":"keep clear of something unwanted"},{"contextId":"u1_03_avoid_paraphrase","text":"The new bypass helps commuters avoid the busiest roads.","meaning":"deliberately stay away from something"}],"contextDependentParaphrases":[],"misleadingDistractors":["join","encourage","permit"],"grammarForms":{"base":"avoid","thirdPerson":"avoids","past":"avoided","pastParticiple":"avoided","ing":"avoiding"},"grammarPatterns":["avoid + noun","avoid + -ing"]}]'::jsonb,'["avoidance","avoidable"]'::jsonb,'[]'::jsonb,'live'),
('vocab_afford','afford','verb','to have enough money, time, or resources for something','[{"senseId":"afford_1","meaning":"to have enough money, time, or resources for something","acceptedParaphrases":["have enough money for","be able to pay for"],"masteryContexts":[{"contextId":"u1_04_afford_meaning","text":"The club had to cancel the trip because it could no longer afford the cost of the coach.","meaning":"have enough resources for a cost"},{"contextId":"u1_04_afford_paraphrase","text":"My parents would love a bigger house, but they simply cannot afford one on a teacher’s salary.","meaning":"be financially able to pay"}],"contextDependentParaphrases":[],"misleadingDistractors":["borrow","recommend","estimate"],"grammarForms":{"base":"afford","thirdPerson":"affords","past":"afforded","pastParticiple":"afforded","ing":"affording"},"grammarPatterns":["can/could afford + noun","can/could afford + to-infinitive"],"teacherNote":"Usually tests ability to pay for something; avoid treating it as a general synonym for buy."}]'::jsonb,'["affordable","unaffordable"]'::jsonb,'["afford the cost","cannot afford"]'::jsonb,'live'),
('vocab_deny','deny','verb','to say that something is not true','[{"senseId":"deny_1","meaning":"to say that something is not true","acceptedParaphrases":["say is not true","reject a claim"],"masteryContexts":[{"contextId":"u1_05_deny_meaning","text":"The company continues to deny any responsibility for the accident, despite the evidence.","meaning":"state that a claim is false"},{"contextId":"u1_05_deny_paraphrase","text":"Both players deny breaking the rules, but the video clearly shows that they did.","meaning":"declare an accusation to be untrue"}],"contextDependentParaphrases":[],"misleadingDistractors":["confirm","admit","allow"],"grammarForms":{"base":"deny","thirdPerson":"denies","past":"denied","pastParticiple":"denied","ing":"denying"},"grammarPatterns":["deny + -ing","deny + that-clause"],"teacherNote":"Use the say-something-is-not-true sense here; the refusal sense is separate."}]'::jsonb,'["denial","undeniable"]'::jsonb,'[]'::jsonb,'live'),
('vocab_permit','permit','verb','to allow something to happen','[{"senseId":"permit_1","meaning":"to allow something to happen","acceptedParaphrases":["allow","give permission for"],"masteryContexts":[{"contextId":"u1_06_permit_meaning","text":"Our flexible timetable will permit you to study at your own pace.","meaning":"make something allowed"},{"contextId":"u1_06_permit_paraphrase","text":"The council will not permit anyone to build on the old playing field, because it is protected land.","meaning":"officially allow something"}],"contextDependentParaphrases":[],"misleadingDistractors":["prevent","demand","resent"],"grammarForms":{"base":"permit","thirdPerson":"permits","past":"permitted","pastParticiple":"permitted","ing":"permitting"},"grammarPatterns":["permit + object + to-infinitive","permit + -ing","be permitted + to-infinitive"]}]'::jsonb,'["permission","permissible"]'::jsonb,'[]'::jsonb,'live'),
('vocab_arrange','arrange','verb','to organise or make plans for something','[{"senseId":"arrange_1","meaning":"to organise or make plans for something","acceptedParaphrases":["organise","plan"],"masteryContexts":[{"contextId":"u1_07_arrange_meaning","text":"Please arrange a time that suits everyone so that we can all meet on Saturday.","meaning":"make plans for something in advance"},{"contextId":"u1_07_arrange_paraphrase","text":"My uncle has offered to arrange transport to the airport for the whole team.","meaning":"put necessary plans in place"}],"contextDependentParaphrases":[],"misleadingDistractors":["cancel","deny","estimate"],"grammarForms":{"base":"arrange","thirdPerson":"arranges","past":"arranged","pastParticiple":"arranged","ing":"arranging"},"grammarPatterns":["arrange + noun","arrange + to-infinitive","arrange for + object + to-infinitive"]}]'::jsonb,'["arrangement","rearrange"]'::jsonb,'[]'::jsonb,'live'),
('vocab_urge','urge','verb','to strongly encourage someone to do something','[{"senseId":"urge_1","meaning":"to strongly encourage someone to do something","acceptedParaphrases":["strongly encourage","press"],"masteryContexts":[{"contextId":"u1_08_urge_meaning","text":"Doctors strongly urge patients to take up gentle exercise because the benefits are so large, though the choice is always theirs.","meaning":"press someone strongly to act"},{"contextId":"u1_08_urge_paraphrase","text":"Friends who live here urge new students to try the local food, which is cheap, delicious and unlike anything most newcomers have tasted.","meaning":"push someone firmly toward action"}],"contextDependentParaphrases":[],"misleadingDistractors":["forbid","ignore","estimate"],"grammarForms":{"base":"urge","thirdPerson":"urges","past":"urged","pastParticiple":"urged","ing":"urging"},"grammarPatterns":["urge + object + to-infinitive","be urged + to-infinitive"]}]'::jsonb,'[]'::jsonb,'[]'::jsonb,'live'),
('vocab_recommend','recommend','verb','to suggest something as suitable or useful','[{"senseId":"recommend_1","meaning":"to suggest something as suitable or useful","acceptedParaphrases":["suggest","advise"],"masteryContexts":[{"contextId":"u1_09_recommend_meaning","text":"My dentist has just retired, so I am asking my colleagues to recommend someone they have been happy with.","meaning":"present something as a suitable choice"},{"contextId":"u1_09_recommend_paraphrase","text":"I would highly recommend the new science museum; my whole class thought it was brilliant.","meaning":"advise choosing a particular option"}],"contextDependentParaphrases":[],"misleadingDistractors":["forbid","demand","deny"],"grammarForms":{"base":"recommend","thirdPerson":"recommends","past":"recommended","pastParticiple":"recommended","ing":"recommending"},"grammarPatterns":["recommend + -ing","recommend + noun + to + person","recommend + that-clause"]}]'::jsonb,'["recommendation","recommended"]'::jsonb,'["strongly recommend","recommend doing"]'::jsonb,'live'),
('vocab_demand','demand','verb','to require a lot of effort, skill, attention, or resources','[{"senseId":"demand_1","meaning":"to require a lot of effort, skill, attention, or resources","acceptedParaphrases":["require","need"],"masteryContexts":[{"contextId":"u1_10_demand_meaning","text":"Marathon training can demand patience, discipline and a great deal of time.","meaning":"require considerable effort or attention"},{"contextId":"u1_10_demand_paraphrase","text":"Learning two languages at once will demand a lot of concentration.","meaning":"place heavy requirements on something"}],"contextDependentParaphrases":[],"misleadingDistractors":["avoid","permit","relax"],"grammarForms":{"base":"demand","thirdPerson":"demands","past":"demanded","pastParticiple":"demanded","ing":"demanding"},"grammarPatterns":["demand + noun","demand + that-clause"]}]'::jsonb,'[]'::jsonb,'["demand time","physically demanding"]'::jsonb,'live')
