('u1_phrase_regardless_rain',1,'phrase_set','{"originalPhrase":"despite the light rain","equivalentPhrase":"regardless of the light rain","acceptedVariants":["in spite of the light rain"],"chunks":["regardless","of","the light rain"],"commonMeaningDistortions":["because of the light rain","only if it rains","as a result of the light rain"],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless"}'::jsonb,'live'),
('u1_phrase_minimum_three',1,'phrase_set','{"originalPhrase":"at least three sessions","equivalentPhrase":"a minimum of three sessions","acceptedVariants":["no fewer than three sessions"],"chunks":["a minimum","of three","sessions"],"commonMeaningDistortions":["no more than three sessions","exactly three sessions only","fewer than three sessions"],"linkedVocabularyIds":["vocab_minimum"],"primaryEvidenceTargetId":"vocab_minimum"}'::jsonb,'live'),
('u1_idea_preference',1,'idea_set','{"originalIdea":"Mina has a preference for individual sports rather than team games.","accurateParaphrases":["Mina likes individual sports more than team games.","Mina would rather play individual sports than team games.","Mina favours taking part in individual sports over team games."],"meaningInvariants":[{"type":"comparison","value":"individual sports preferred to team games"}],"distractors":[{"text":"Mina likes team games more than individual sports.","misconceptionCategory":"meaning_confusion"},{"text":"Mina likes individual sports and team games equally.","misconceptionCategory":"degree_change"},{"text":"Mina only takes part in team games and avoids individual sports.","misconceptionCategory":"added_information"}],"linkedVocabularyIds":["vocab_preference"],"primaryEvidenceTargetId":"vocab_preference"}'::jsonb,'live'),
('u1_idea_deny',1,'idea_set','{"originalIdea":"The athlete denied using any banned substance.","accurateParaphrases":["The athlete said it was not true that he had used a banned substance.","The athlete rejected the claim that he had used a banned substance.","The athlete stated that he had not used any banned substance."],"meaningInvariants":[{"type":"polarity","value":"claim is rejected"}],"distractors":[{"text":"The athlete admitted that he had used a banned substance.","misconceptionCategory":"meaning_confusion"},{"text":"The athlete refused to comment on whether he had used a banned substance.","misconceptionCategory":"omitted_information"},{"text":"The athlete confirmed the claim that he had used a banned substance.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_deny"],"primaryEvidenceTargetId":"vocab_deny"}'::jsonb,'live'),
('u1_idea_permit',1,'idea_set','{"originalIdea":"The club does not permit spectators to enter the training area.","accurateParaphrases":["Spectators are not allowed to go into the training area.","The club does not let spectators into the training area.","Entry to the training area is not allowed for spectators."],"meaningInvariants":[{"type":"polarity","value":"permission is refused"}],"distractors":[{"text":"Spectators are allowed to enter the training area whenever they want.","misconceptionCategory":"meaning_confusion"},{"text":"Only the coaches are forbidden from entering the training area.","misconceptionCategory":"meaning_confusion"},{"text":"Spectators are required to enter the training area before practice.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_permit"],"primaryEvidenceTargetId":"vocab_permit"}'::jsonb,'live'),
('u1_idea_intense',1,'idea_set','{"originalIdea":"The final ten minutes of the match were intense.","accurateParaphrases":["The last ten minutes of the match were extremely demanding.","The match was extremely demanding in its final ten minutes.","The final ten minutes of the game were extremely demanding."],"meaningInvariants":[{"type":"degree","value":"very strong or demanding"}],"distractors":[{"text":"The final ten minutes of the match were calm and relaxed.","misconceptionCategory":"degree_change"},{"text":"Only the first ten minutes of the match were extremely demanding.","misconceptionCategory":"time_change"},{"text":"The final ten minutes of the match were only slightly demanding.","misconceptionCategory":"degree_change"}],"linkedVocabularyIds":["vocab_intense"],"primaryEvidenceTargetId":"vocab_intense"}'::jsonb,'live'),
('u1_idea_tournament',1,'idea_set','{"originalIdea":"Teams from eight schools entered the regional tournament.","accurateParaphrases":["Eight schools sent teams to take part in the regional competition.","Eight schools put their teams into the regional competition.","The regional competition included teams from eight schools."],"meaningInvariants":[{"type":"quantity","value":"eight schools"}],"distractors":[{"text":"Teams from every school in the region entered the tournament.","misconceptionCategory":"quantity_change"},{"text":"Eight individual students entered one regional match.","misconceptionCategory":"meaning_confusion"},{"text":"Eight schools watched the regional competition but did not enter teams.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_tournament"],"primaryEvidenceTargetId":"vocab_tournament"}'::jsonb,'live'),
('u1_idea_discipline',1,'idea_set','{"originalIdea":"Daily training requires discipline as well as ability.","accurateParaphrases":["Training every day needs self-control in addition to ability.","Both self-control and ability are needed for daily training.","Daily training depends on self-control as well as ability."],"meaningInvariants":[{"type":"addition","value":"self-control and ability are both required"}],"distractors":[{"text":"Ability alone is enough for someone who trains every day.","misconceptionCategory":"omitted_information"},{"text":"Self-control is needed for daily training, but ability is unnecessary.","misconceptionCategory":"omitted_information"},{"text":"Occasional training requires ability but no consistent self-control.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_discipline"],"primaryEvidenceTargetId":"vocab_discipline"}'::jsonb,'live'),
('u1_idea_overwhelming',1,'idea_set','{"originalIdea":"The support from the crowd was overwhelming during the final.","accurateParaphrases":["During the final, the crowd gave support that was extremely powerful.","During the final, the support from the crowd was extremely strong.","The support the crowd gave during the final was extremely strong."],"meaningInvariants":[{"type":"degree","value":"support is extremely strong"}],"distractors":[{"text":"The crowd gave only a small amount of support during the final.","misconceptionCategory":"degree_change"},{"text":"The crowd support during the final was noticeable but easy to manage.","misconceptionCategory":"degree_change"},{"text":"The crowd gave extremely powerful support before the final but not during it.","misconceptionCategory":"time_change"}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming"}'::jsonb,'live'),
('u1_idea_generation',1,'idea_set','{"originalIdea":"A new generation of players is entering the professional game.","accurateParaphrases":["A younger age group of players is beginning to compete professionally.","A younger group of players is starting to play professionally.","Players from a younger age group are now joining the professional game."],"meaningInvariants":[{"type":"time_group","value":"younger age group"}],"distractors":[{"text":"Only one new player is entering the professional game.","misconceptionCategory":"quantity_change"},{"text":"An older age group of players is beginning to compete professionally.","misconceptionCategory":"meaning_confusion"},{"text":"A younger age group of players is leaving professional competition.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation"}'::jsonb,'live'),
('u1_idea_solution',1,'idea_set','{"originalIdea":"The club found a solution to the shortage of training space.","accurateParaphrases":["The club found a way to deal with not having enough training space.","The club worked out how to solve its shortage of training space.","The club found an answer to its lack of training space."],"meaningInvariants":[{"type":"cause_effect","value":"solution addresses shortage"}],"distractors":[{"text":"The shortage of training space was caused by the club’s solution.","misconceptionCategory":"cause_effect_change"},{"text":"The club decided to ignore the shortage of training space.","misconceptionCategory":"omitted_information"},{"text":"The club made the shortage of training space more difficult to solve.","misconceptionCategory":"cause_effect_change"}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution"}'::jsonb,'live'),
('u1_idea_pastime',1,'idea_set','{"originalIdea":"Cycling began as a pastime before it became her profession.","accurateParaphrases":["She first cycled as a hobby and later made it her career.","Cycling started as a hobby for her and later became her job.","Before cycling became her career, it was something she did for fun."],"meaningInvariants":[{"type":"time","value":"hobby came before profession"}],"distractors":[{"text":"Cycling became her profession before she tried it as a hobby.","misconceptionCategory":"time_change"},{"text":"Cycling was always her profession and was never a hobby.","misconceptionCategory":"omitted_information"},{"text":"Cycling remained only a hobby and never became her career.","misconceptionCategory":"omitted_information"}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime"}'::jsonb,'live'),
('u1_idea_estimated',1,'idea_set','{"originalIdea":"The estimated cost of the new sports centre is five million dollars.","accurateParaphrases":["The sports centre is expected to cost about five million dollars.","The cost of the new sports centre is approximately five million dollars.","The expected cost of the new sports centre is roughly five million dollars."],"meaningInvariants":[{"type":"certainty","value":"figure is approximate"}],"distractors":[{"text":"The sports centre definitely costs exactly five million dollars.","misconceptionCategory":"degree_change"},{"text":"The sports centre has already cost exactly five million dollars.","misconceptionCategory":"time_change"},{"text":"No one has made any approximate calculation of the sports centre’s cost.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated"}'::jsonb,'live'),
('u1_idea_relatively',1,'idea_set','{"originalIdea":"The new sports centre is relatively small compared with the old stadium.","accurateParaphrases":["Compared with the old stadium, the new sports centre is fairly small.","The new sports centre is comparatively small when set against the old stadium.","The new sports centre is fairly small in comparison with the old stadium."],"meaningInvariants":[{"type":"comparison","value":"size is judged relative to old stadium"}],"distractors":[{"text":"The new sports centre is extremely small in every possible comparison.","misconceptionCategory":"degree_change"},{"text":"The new sports centre and the old stadium are exactly the same size.","misconceptionCategory":"meaning_confusion"},{"text":"Compared with the new sports centre, the old stadium is fairly small.","misconceptionCategory":"meaning_confusion"}],"linkedVocabularyIds":["vocab_relatively"],"primaryEvidenceTargetId":"vocab_relatively"}'::jsonb,'live'),
('u1_qt_training_costs',1,'question_text','{"sourceText":"A local club wanted to replace its training equipment, but the original plan was too expensive. Instead, members repaired several machines and bought only the items that could not be fixed.","questions":[{"question":"Why did the club change its original plan?","evidenceSpans":["the original plan was too expensive"],"paraphraseLinks":[{"questionText":"Why did the club change its original plan?","sourceText":"the original plan was too expensive"}]},{"question":"What did members do instead of replacing everything?","evidenceSpans":["members repaired several machines and bought only the items that could not be fixed"],"paraphraseLinks":[{"questionText":"instead of replacing everything","sourceText":"repaired several machines and bought only the items that could not be fixed"}]}],"linkedVocabularyIds":["vocab_afford","vocab_solution"]}'::jsonb,'live'),
('u1_qt_tournament_entry',1,'question_text','{"sourceText":"The regional tournament attracted teams from eight schools. Competitors had to register before Friday, and anyone who missed the deadline was not permitted to take part.","questions":[{"question":"How many schools were represented?","evidenceSpans":["teams from eight schools"],"paraphraseLinks":[{"questionText":"How many schools were represented?","sourceText":"teams from eight schools"}]},{"question":"Who could not participate?","evidenceSpans":["anyone who missed the deadline was not permitted to take part"],"paraphraseLinks":[{"questionText":"could not participate","sourceText":"was not permitted to take part"}]}],"linkedVocabularyIds":["vocab_tournament","vocab_competitor","vocab_permit"]}'::jsonb,'live'),
('u1_qt_determined_runner',1,'question_text','{"sourceText":"Lina fell behind early in the race, but she remained determined to finish. She ignored the urge to stop, kept a steady pace and crossed the line several minutes after the leading runners.","questions":[{"question":"What shows that Lina did not give up?","evidenceSpans":["she remained determined to finish"],"paraphraseLinks":[{"questionText":"did not give up","sourceText":"remained determined to finish"}]},{"question":"When did she finish compared with the leaders?","evidenceSpans":["several minutes after the leading runners"],"paraphraseLinks":[{"questionText":"compared with the leaders","sourceText":"after the leading runners"}]}],"linkedVocabularyIds":["vocab_determined","vocab_urge"]}'::jsonb,'live'),
('u1_qt_community_club',1,'question_text','{"sourceText":"A community club has built a strong reputation for welcoming beginners. The atmosphere is friendly, fees are reasonable, and coaches recommend activities according to each member’s experience.","questions":[{"question":"Why might a beginner feel comfortable there?","evidenceSpans":["The atmosphere is friendly"],"paraphraseLinks":[{"questionText":"feel comfortable","sourceText":"atmosphere is friendly"}]},{"question":"How do coaches choose activities for members?","evidenceSpans":["according to each member’s experience"],"paraphraseLinks":[{"questionText":"choose activities for members","sourceText":"according to each member’s experience"}]}],"linkedVocabularyIds":["vocab_reputation","vocab_atmosphere","vocab_reasonable","vocab_recommend"]}'::jsonb,'live'),
('u1_qt_sports_centre',1,'question_text','{"sourceText":"The estimated cost of the sports centre was high, so planners reduced the first phase of the project. Even after the change, the centre still included the minimum number of courts required for regional events.","questions":[{"question":"Why was the first phase made smaller?","evidenceSpans":["The estimated cost of the sports centre was high"],"paraphraseLinks":[{"questionText":"Why was the first phase made smaller?","sourceText":"estimated cost ... was high"}]},{"question":"What requirement did the revised plan still satisfy?","evidenceSpans":["the minimum number of courts required for regional events"],"paraphraseLinks":[{"questionText":"requirement did the revised plan still satisfy","sourceText":"minimum number of courts required"}]}],"linkedVocabularyIds":["vocab_estimated","vocab_minimum"]}'::jsonb,'live'),
('u1_qt_craft_market',1,'question_text','{"sourceText":"At the weekend market, local craftspeople produce traditional wooden games by hand. Their work has gained a significant reputation, and some pieces are now collected as antiques rather than used for play.","questions":[{"question":"How are the traditional games made?","evidenceSpans":["by hand"],"paraphraseLinks":[{"questionText":"How are the traditional games made?","sourceText":"by hand"}]},{"question":"Why are some pieces no longer used for play?","evidenceSpans":["some pieces are now collected as antiques rather than used for play"],"paraphraseLinks":[{"questionText":"no longer used for play","sourceText":"collected as antiques rather than used for play"}]}],"linkedVocabularyIds":["vocab_craftspeople","vocab_produce","vocab_significant","vocab_antiques"]}'::jsonb,'live'),
('u1_qt_young_players',1,'question_text','{"sourceText":"A younger generation of players has joined the league, creating rapid expansion in junior teams. Organisers say the growth is positive, although finding enough qualified coaches remains a challenge.","questions":[{"question":"What has caused junior teams to grow quickly?","evidenceSpans":["A younger generation of players has joined the league"],"paraphraseLinks":[{"questionText":"caused junior teams to grow quickly","sourceText":"younger generation of players has joined"}]},{"question":"What problem has not yet been solved?","evidenceSpans":["finding enough qualified coaches remains a challenge"],"paraphraseLinks":[{"questionText":"problem has not yet been solved","sourceText":"remains a challenge"}]}],"linkedVocabularyIds":["vocab_generation","vocab_expansion","vocab_challenge"]}'::jsonb,'live'),
('u1_qt_championship_pressure',1,'question_text','{"sourceText":"Before the national championship, the team faced an intense training schedule. The captain said success depended on discipline and patience, especially when progress seemed relatively slow.","questions":[{"question":"What qualities did the captain say were necessary?","evidenceSpans":["discipline and patience"],"paraphraseLinks":[{"questionText":"qualities ... necessary","sourceText":"depended on discipline and patience"}]},{"question":"When were those qualities particularly important?","evidenceSpans":["when progress seemed relatively slow"],"paraphraseLinks":[{"questionText":"particularly important","sourceText":"especially when progress seemed relatively slow"}]}],"linkedVocabularyIds":["vocab_championship","vocab_intense","vocab_discipline","vocab_patience","vocab_relatively"]}'::jsonb,'live'),
('u1_qt_historic_win',1,'question_text','{"sourceText":"The small club achieved a historic victory after defeating an elite opponent. Supporters described the result as an incredible feat because the team had struggled financially for several seasons.","questions":[{"question":"Why was the result especially impressive?","evidenceSpans":["the team had struggled financially for several seasons"],"paraphraseLinks":[{"questionText":"Why was the result especially impressive?","sourceText":"struggled financially for several seasons"}]},{"question":"How important was the victory to the club’s history?","evidenceSpans":["a historic victory"],"paraphraseLinks":[{"questionText":"important ... to the club’s history","sourceText":"historic victory"}]}],"linkedVocabularyIds":["vocab_historic","vocab_elite","vocab_incredible","vocab_feat","vocab_struggle"]}'::jsonb,'live'),
('u1_qt_activity_selection',1,'question_text','{"sourceText":"The centre offers a wide selection of free-time activities, from racquet sports to crafts. Staff arrange short introductory sessions so that visitors can try unfamiliar activities before deciding which ones they prefer.","questions":[{"question":"Why are introductory sessions provided?","evidenceSpans":["visitors can try unfamiliar activities before deciding which ones they prefer"],"paraphraseLinks":[{"questionText":"Why are introductory sessions provided?","sourceText":"try unfamiliar activities before deciding which ones they prefer"}]},{"question":"What variety does the centre provide?","evidenceSpans":["a wide selection of free-time activities, from racquet sports to crafts"],"paraphraseLinks":[{"questionText":"What variety does the centre provide?","sourceText":"wide selection ... from racquet sports to crafts"}]}],"linkedVocabularyIds":["vocab_selection","vocab_leisure","vocab_racquet","vocab_arrange","vocab_unfamiliar","vocab_preference"]}'::jsonb,'live'),
('u1_writing_avoid_repeat',1,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace the repeated general adjective with a more precise Unit 1 word.","sourceText":"The final was very strong and the pressure during the final was very strong.","acceptedAnswers":["intense"],"linkedVocabularyIds":["vocab_intense"],"primaryEvidenceTargetId":"vocab_intense"}'::jsonb,'live'),
('u1_writing_achievement_collocation',1,'writing_set','{"taskType":"collocation","prompt":"Complete the phrase with the natural Unit 1 noun.","sourceText":"Winning the regional title was a major ____.","acceptedAnswers":["achievement"],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement"}'::jsonb,'live'),
('u1_writing_selection_range',1,'writing_set','{"taskType":"improve_vocabulary","prompt":"Replace “many different choices” with a concise Unit 1 expression.","sourceText":"The sports centre offers many different choices of after-school activities.","acceptedAnswers":["a wide selection","wide selection"],"linkedVocabularyIds":["vocab_selection"],"primaryEvidenceTargetId":"vocab_selection"}'::jsonb,'live'),
('u1_writing_reasonable_fee',1,'writing_set','{"taskType":"collocation","prompt":"Choose the natural adjective to describe a fair, not excessive price.","sourceText":"Students said the membership fee was ____.","acceptedAnswers":["reasonable"],"linkedVocabularyIds":["vocab_reasonable"],"primaryEvidenceTargetId":"vocab_reasonable"}'::jsonb,'live'),
('u1_writing_word_family_compete',1,'writing_set','{"taskType":"word_family","prompt":"Use the correct form from the compete word family.","sourceText":"Each ____ must register before the race begins.","acceptedAnswers":["competitor"],"linkedVocabularyIds":["vocab_competitor"],"primaryEvidenceTargetId":"vocab_competitor"}'::jsonb,'live'),
