('u1_writing_word_family_prefer',1,'writing_set','{"taskType":"word_family","prompt":"Use the correct form from the preference word family.","sourceText":"Many students ____ individual sports to team games.","acceptedAnswers":["prefer"],"linkedVocabularyIds":["vocab_preference"],"primaryEvidenceTargetId":"vocab_preference"}'::jsonb,'live'),
('u1_writing_word_family_afford',1,'writing_set','{"taskType":"word_family","prompt":"Use the correct form from the afford word family.","sourceText":"The club reduced its fees to make membership more ____.","acceptedAnswers":["affordable"],"linkedVocabularyIds":["vocab_afford"],"primaryEvidenceTargetId":"vocab_afford"}'::jsonb,'live'),
('u1_writing_word_family_permit',1,'writing_set','{"taskType":"word_family","prompt":"Use the correct form from the permit word family.","sourceText":"Students need ____ to use the gym after school.","acceptedAnswers":["permission"],"linkedVocabularyIds":["vocab_permit"],"primaryEvidenceTargetId":"vocab_permit"}'::jsonb,'live'),
('u1_writing_word_family_arrange',1,'writing_set','{"taskType":"word_family","prompt":"Use the correct form from the arrange word family.","sourceText":"The transport ____ was confirmed before the tournament.","acceptedAnswers":["arrangement"],"linkedVocabularyIds":["vocab_arrange"],"primaryEvidenceTargetId":"vocab_arrange"}'::jsonb,'live'),
('u1_writing_word_family_recommend',1,'writing_set','{"taskType":"word_family","prompt":"Use the correct form from the recommend word family.","sourceText":"The coach made a ____ to add an extra recovery session.","acceptedAnswers":["recommendation"],"linkedVocabularyIds":["vocab_recommend"],"primaryEvidenceTargetId":"vocab_recommend"}'::jsonb,'live'),
