('u1_writing_word_family_produce_b',1,'writing_set','{"taskType":"word_family","prompt":"Use the correct form from the produce word family.","sourceText":"The workshop is the main _____ of handmade sports equipment in the area.","acceptedAnswers":["producer"],"linkedVocabularyIds":["vocab_produce"],"primaryEvidenceTargetId":"vocab_produce"}'::jsonb,'live'),
