('language-bank:leisure_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Many students use their ____ to play sport or meet friends.","acceptedAnswers":["leisure time"],"distractors":[{"text":"study time","reason":"Fits grammatically, but the sentence describes time used for recreation rather than study."},{"text":"working hours","reason":"Fits grammatically, but the sentence describes time away from work."},{"text":"lesson time","reason":"Fits grammatically, but the activities happen outside lessons."}],"linkedVocabularyIds":["vocab_leisure"],"primaryEvidenceTargetId":"vocab_leisure","languageBankContextId":"leisure_ctx_1"}'::jsonb,'live'),
('language-bank:leisure_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The council built new ____ facilities so residents could exercise and relax after work.","acceptedAnswers":["leisure"],"distractors":[{"text":"office","reason":"Can modify facilities, but offices are for work rather than recreation."},{"text":"factory","reason":"Can modify facilities, but factories are workplaces rather than places for recreation."},{"text":"school","reason":"Can modify facilities, but the sentence specifies facilities for residents to relax after work, not for lessons."}],"linkedVocabularyIds":["vocab_leisure"],"primaryEvidenceTargetId":"vocab_leisure","languageBankContextId":"leisure_ctx_2"}'::jsonb,'live'),
('language-bank:leisure_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Reading and gardening are popular ____ activities among retired people.","acceptedAnswers":["leisure"],"distractors":[{"text":"work","reason":"Fits before activities, but reading and gardening are described here as recreation."},{"text":"school","reason":"Fits before activities, but the sentence refers to retired people and free-time pursuits."},{"text":"medical","reason":"Fits before activities grammatically, but the examples are recreational rather than medical."}],"linkedVocabularyIds":["vocab_leisure"],"primaryEvidenceTargetId":"vocab_leisure","languageBankContextId":"leisure_ctx_3"}'::jsonb,'live'),
('language-bank:leisure_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The report examines how families spend their ____ at weekends.","acceptedAnswers":["leisure time"],"distractors":[{"text":"working hours","reason":"Fits grammatically, but weekends are being discussed as time away from work."},{"text":"lesson time","reason":"Fits grammatically, but the sentence concerns family recreation rather than lessons."},{"text":"office time","reason":"Fits grammatically, but the report is about time away from employment."}],"linkedVocabularyIds":["vocab_leisure"],"primaryEvidenceTargetId":"vocab_leisure","languageBankContextId":"leisure_ctx_4"}'::jsonb,'live'),
('language-bank:leisure_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The hotel has a ____ centre with a swimming pool and gym.","acceptedAnswers":["leisure"],"distractors":[{"text":"business","reason":"Can modify centre, but a pool and gym identify a recreation facility rather than a business centre."},{"text":"conference","reason":"Can modify centre, but a conference centre is for meetings, not the facilities described."},{"text":"medical","reason":"Can modify centre, but the sentence describes recreation facilities rather than treatment services."}],"linkedVocabularyIds":["vocab_leisure"],"primaryEvidenceTargetId":"vocab_leisure","languageBankContextId":"leisure_ctx_5"}'::jsonb,'live'),
('language-bank:leisure_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Cycling started as a ____ activity for her before becoming a full-time job.","acceptedAnswers":["leisure"],"distractors":[{"text":"professional","reason":"Fits grammatically, but contradicts the contrast with becoming a full-time job later."},{"text":"paid","reason":"Fits grammatically, but contradicts the idea that it only later became a job."},{"text":"business","reason":"Fits grammatically, but the sentence contrasts recreation with later employment."}],"linkedVocabularyIds":["vocab_leisure"],"primaryEvidenceTargetId":"vocab_leisure","languageBankContextId":"leisure_ctx_6"}'::jsonb,'live'),
('language-bank:avoid_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Try to ____ eating a big meal just before you swim.","acceptedAnswers":["avoid"],"distractors":[{"text":"continue","reason":"Grammatically fits before -ing, but gives the opposite advice."},{"text":"consider","reason":"Grammatically fits before -ing, but means think about doing it rather than keep away from it."},{"text":"enjoy","reason":"Grammatically fits before -ing, but expresses pleasure rather than keeping away from the action."}],"linkedVocabularyIds":["vocab_avoid"],"primaryEvidenceTargetId":"vocab_avoid","languageBankContextId":"avoid_ctx_1"}'::jsonb,'live'),
('language-bank:avoid_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The new bypass helps commuters ____ the busiest roads.","acceptedAnswers":["avoid"],"distractors":[{"text":"use","reason":"Grammatically fits the object, but means travel on those roads rather than keep away from them."},{"text":"follow","reason":"Grammatically fits the object, but means travel along those roads."},{"text":"enter","reason":"Grammatically fits the object, but means go onto those roads."}],"linkedVocabularyIds":["vocab_avoid"],"primaryEvidenceTargetId":"vocab_avoid","languageBankContextId":"avoid_ctx_2"}'::jsonb,'live'),
('language-bank:avoid_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Wear protective pads to ____ unnecessary injuries during training.","acceptedAnswers":["avoid"],"distractors":[{"text":"risk","reason":"Grammatically fits, but means expose yourself to the possibility of injury."},{"text":"cause","reason":"Grammatically fits, but means make the injuries happen."},{"text":"report","reason":"Grammatically fits, but means describe the injuries after they happen."}],"linkedVocabularyIds":["vocab_avoid"],"primaryEvidenceTargetId":"vocab_avoid","languageBankContextId":"avoid_ctx_3"}'::jsonb,'live'),
('language-bank:avoid_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"She changed her route to ____ the roadworks near the stadium.","acceptedAnswers":["avoid"],"distractors":[{"text":"reach","reason":"Grammatically fits, but means arrive at the roadworks."},{"text":"cross","reason":"Grammatically fits, but means travel through the roadworks."},{"text":"follow","reason":"Grammatically fits, but means travel along the affected route."}],"linkedVocabularyIds":["vocab_avoid"],"primaryEvidenceTargetId":"vocab_avoid","languageBankContextId":"avoid_ctx_4"}'::jsonb,'live'),
('language-bank:avoid_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Doctors advise people to ____ sugary drinks whenever possible.","acceptedAnswers":["avoid"],"distractors":[{"text":"choose","reason":"Grammatically fits, but means select the drinks."},{"text":"serve","reason":"Grammatically fits, but means provide the drinks to other people."},{"text":"buy","reason":"Grammatically fits, but means purchase the drinks."}],"linkedVocabularyIds":["vocab_avoid"],"primaryEvidenceTargetId":"vocab_avoid","languageBankContextId":"avoid_ctx_5"}'::jsonb,'live'),
('language-bank:avoid_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"To reduce stress, he tries to ____ arguments before important matches.","acceptedAnswers":["avoid"],"distractors":[{"text":"start","reason":"Grammatically fits, but means begin the arguments."},{"text":"continue","reason":"Grammatically fits, but means keep the arguments going."},{"text":"win","reason":"Grammatically fits, but focuses on succeeding in an argument rather than keeping away from one."}],"linkedVocabularyIds":["vocab_avoid"],"primaryEvidenceTargetId":"vocab_avoid","languageBankContextId":"avoid_ctx_6"}'::jsonb,'live'),
('language-bank:preference_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The survey showed that most people have a strong ____ for fresh food over tinned food.","acceptedAnswers":["preference"],"distractors":[{"text":"need","reason":"Fits grammatically, but a need is something required, while over tinned food shows one option being favoured."},{"text":"demand","reason":"Fits grammatically, but demand means how much people want to buy a product, not one option being liked more than another."},{"text":"concern","reason":"Fits grammatically, but concern means worry; nothing in the sentence is a worry."}],"linkedVocabularyIds":["vocab_preference"],"primaryEvidenceTargetId":"vocab_preference","languageBankContextId":"preference_ctx_1"}'::jsonb,'live'),
('language-bank:preference_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"When I booked the flight, the website asked whether I had a ____ for a window or an aisle seat.","acceptedAnswers":["preference"],"distractors":[{"text":"priority","reason":"Fits grammatically, but a priority is what must come first, not which of two seats you like better."},{"text":"requirement","reason":"Fits grammatically, but a requirement is a must-have; the website is offering a free choice between two seats."},{"text":"reservation","reason":"Fits grammatically, but a reservation is a booking, and the flight is already booked; the question is about which seat you favour."}],"linkedVocabularyIds":["vocab_preference"],"primaryEvidenceTargetId":"vocab_preference","languageBankContextId":"preference_ctx_2"}'::jsonb,'live'),
('language-bank:preference_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"List the three clubs in order of ____, starting with the one you would most like to join.","acceptedAnswers":["preference"],"distractors":[{"text":"importance","reason":"Fits grammatically, but importance ranks what matters most, but the sentence asks which club you would most like to join."},{"text":"popularity","reason":"Fits grammatically, but popularity measures what many students like, but the sentence asks for your own ranking."},{"text":"distance","reason":"Fits grammatically, but distance ranks how far away each club is, not how much you want to join it."}],"linkedVocabularyIds":["vocab_preference"],"primaryEvidenceTargetId":"vocab_preference","languageBankContextId":"preference_ctx_3"}'::jsonb,'live'),
('language-bank:preference_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"My brother has a ____ for science fiction, so I bought him a novel from that section.","acceptedAnswers":["preference"],"distractors":[{"text":"talent","reason":"Fits grammatically, but a talent is an ability; the gift depends on what he likes to read, not what he can do."},{"text":"reputation","reason":"Fits grammatically, but a reputation is how other people see him; the gift depends on what he likes himself."},{"text":"respect","reason":"Fits grammatically, but respect is admiration; buying him a novel shows what he enjoys reading."}],"linkedVocabularyIds":["vocab_preference"],"primaryEvidenceTargetId":"vocab_preference","languageBankContextId":"preference_ctx_4"}'::jsonb,'live'),
('language-bank:preference_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her ____ is for coursework rather than exams, because she says she works better without time pressure.","acceptedAnswers":["preference"],"distractors":[{"text":"strength","reason":"Fits grammatically, but a strength is something she does well, but the reason given is what she likes working on."},{"text":"advantage","reason":"Fits grammatically, but an advantage is a benefit she has; the sentence gives her reason for liking one kind of assessment more."},{"text":"excuse","reason":"Fits grammatically, but an excuse defends a failure, but the sentence gives a positive reason for her liking."}],"linkedVocabularyIds":["vocab_preference"],"primaryEvidenceTargetId":"vocab_preference","languageBankContextId":"preference_ctx_5"}'::jsonb,'live'),
('language-bank:preference_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Which team you support is simply a matter of personal ____.","acceptedAnswers":["preference"],"distractors":[{"text":"belief","reason":"Fits grammatically, but a belief is something you think is true, whereas supporting a team is a favourite you choose."},{"text":"judgement","reason":"Fits grammatically, but judgement is a decision about quality or truth, not a favourite you simply like."},{"text":"experience","reason":"Fits grammatically, but experience comes from things that happen to you, not from choosing a favourite team."}],"linkedVocabularyIds":["vocab_preference"],"primaryEvidenceTargetId":"vocab_preference","languageBankContextId":"preference_ctx_6"}'::jsonb,'live'),
('language-bank:afford_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The club had to cancel the trip because it could no longer ____ the cost of the coach.","acceptedAnswers":["afford"],"distractors":[{"text":"reduce","reason":"Fits grammatically, but reduce means make smaller; cancelling the trip shows the club lacked the money, not that it lowered a price."},{"text":"estimate","reason":"Fits grammatically, but estimate means guess a figure; it does not explain why the trip was cancelled."},{"text":"predict","reason":"Fits grammatically, but predict means say what will happen; the problem is not having the money for the coach."}],"linkedVocabularyIds":["vocab_afford"],"primaryEvidenceTargetId":"vocab_afford","languageBankContextId":"afford_ctx_1"}'::jsonb,'live'),
('language-bank:afford_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"My parents would love a bigger house, but they simply cannot ____ one on a teacher’s salary.","acceptedAnswers":["afford"],"distractors":[{"text":"find","reason":"Fits grammatically, but find means discover; the problem named is the salary, not the search."},{"text":"build","reason":"Fits grammatically, but build means construct; the problem named is the salary, not who makes the house."},{"text":"keep","reason":"Fits grammatically, but keep means hold on to; they do not yet have the bigger house."}],"linkedVocabularyIds":["vocab_afford"],"primaryEvidenceTargetId":"vocab_afford","languageBankContextId":"afford_ctx_2"}'::jsonb,'live'),
('language-bank:afford_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Students who work every evening to pay their rent cannot ____ to spend long hours on revision.","acceptedAnswers":["afford"],"distractors":[{"text":"bother","reason":"Fits grammatically, but bother means make the effort, but the reason given is that they must work to pay rent, not a lack of effort."},{"text":"wait","reason":"Fits grammatically, but wait means stay until something happens, which does not explain a lack of spare time."},{"text":"pretend","reason":"Fits grammatically, but pretend means act as if something is true, which does not fit a real lack of time."}],"linkedVocabularyIds":["vocab_afford"],"primaryEvidenceTargetId":"vocab_afford","languageBankContextId":"afford_ctx_3"}'::jsonb,'live'),
('language-bank:afford_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The council lowered the entry fee so that more families could ____ the price of a day at the leisure centre.","acceptedAnswers":["afford"],"distractors":[{"text":"calculate","reason":"Fits grammatically, but calculate means work out a figure, but lowering the fee helps families pay, not work out numbers."},{"text":"estimate","reason":"Fits grammatically, but estimate means guess a figure, but lowering the fee helps families pay, not guess."},{"text":"question","reason":"Fits grammatically, but question means doubt or ask about, but lowering the fee does not change what families can ask."}],"linkedVocabularyIds":["vocab_afford"],"primaryEvidenceTargetId":"vocab_afford","languageBankContextId":"afford_ctx_4"}'::jsonb,'live'),
('language-bank:afford_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"She took a second job because her salary was too low and she could not ____ to fall behind with the rent.","acceptedAnswers":["afford"],"distractors":[{"text":"choose","reason":"Fits grammatically, but choose means decide between options, but the sentence explains the second job by her low salary, which is about money, not a decision."},{"text":"bother","reason":"Fits grammatically, but bother means make the effort, but the reason for the second job is her low salary."},{"text":"intend","reason":"Fits grammatically, but intend means plan to, but she took a second job to avoid falling behind."}],"linkedVocabularyIds":["vocab_afford"],"primaryEvidenceTargetId":"vocab_afford","languageBankContextId":"afford_ctx_5"}'::jsonb,'live'),
('language-bank:afford_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"A new phone is not something we can ____ right now, so we will wait until next year.","acceptedAnswers":["afford"],"distractors":[{"text":"replace","reason":"Fits grammatically, but replace means swap one thing for another; the sentence says they must wait, which points to money."},{"text":"repair","reason":"Fits grammatically, but repair means fix an old phone, but the sentence is about getting a new one."},{"text":"borrow","reason":"Fits grammatically, but borrow would let them have a phone now, but the sentence says they must wait."}],"linkedVocabularyIds":["vocab_afford"],"primaryEvidenceTargetId":"vocab_afford","languageBankContextId":"afford_ctx_6"}'::jsonb,'live'),
('language-bank:deny_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The company continues to ____ any responsibility for the accident, despite the evidence.","acceptedAnswers":["deny"],"distractors":[{"text":"accept","reason":"Fits grammatically, but accept means agree that it is responsible, which contradicts continues and despite the evidence."},{"text":"ignore","reason":"Fits grammatically, but ignore means pay no attention; the company is making a statement about the accident, not ignoring it."},{"text":"take","reason":"Fits grammatically, but take responsibility means accept the blame, which contradicts continues and despite the evidence."}],"linkedVocabularyIds":["vocab_deny"],"primaryEvidenceTargetId":"vocab_deny","languageBankContextId":"deny_ctx_1"}'::jsonb,'live'),
('language-bank:deny_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Both players ____ breaking the rules, but the video clearly shows that they did.","acceptedAnswers":["deny"],"distractors":[{"text":"admit","reason":"Fits grammatically, but admit means agree it is true, but the but-clause shows the players say the opposite."},{"text":"regret","reason":"Fits grammatically, but regret means feel sorry, which would mean they accept they broke the rules."},{"text":"risk","reason":"Fits grammatically, but risk means do something that might cause harm; the sentence is about what the players say they did."}],"linkedVocabularyIds":["vocab_deny"],"primaryEvidenceTargetId":"vocab_deny","languageBankContextId":"deny_ctx_2"}'::jsonb,'live'),
('language-bank:deny_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The singer’s agent issued a statement to ____ the rumour that she was leaving the band, saying it was completely false.","acceptedAnswers":["deny"],"distractors":[{"text":"confirm","reason":"Fits grammatically, but confirm means say it is true, but the statement says the rumour is false."},{"text":"explain","reason":"Fits grammatically, but explain means give reasons, but the statement simply says the rumour is false."},{"text":"back","reason":"Fits grammatically, but back means support, but the statement says the rumour is completely false."}],"linkedVocabularyIds":["vocab_deny"],"primaryEvidenceTargetId":"vocab_deny","languageBankContextId":"deny_ctx_3"}'::jsonb,'live'),
('language-bank:deny_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Shown the photograph, she still continued to ____ that she had been at the party.","acceptedAnswers":["deny"],"distractors":[{"text":"admit","reason":"Fits grammatically, but admit means agree it is true, but still continued shows she kept saying the opposite."},{"text":"claim","reason":"Fits grammatically, but claim means say it is true; the photograph proves she was there, so still signals she says it is false."},{"text":"hint","reason":"Fits grammatically, but hint means suggest indirectly, but still continued shows she kept saying the opposite of what the photograph shows."}],"linkedVocabularyIds":["vocab_deny"],"primaryEvidenceTargetId":"vocab_deny","languageBankContextId":"deny_ctx_4"}'::jsonb,'live'),
('language-bank:deny_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Nobody can ____ that regular exercise improves mood; the evidence is very strong.","acceptedAnswers":["deny"],"distractors":[{"text":"prove","reason":"Fits grammatically, but prove means show it is true, but the second clause says the evidence already exists."},{"text":"show","reason":"Fits grammatically, but show means make something clear, but the second clause says the evidence already exists."},{"text":"predict","reason":"Fits grammatically, but predict means say what will happen, whereas the sentence is about evidence for something already known."}],"linkedVocabularyIds":["vocab_deny"],"primaryEvidenceTargetId":"vocab_deny","languageBankContextId":"deny_ctx_5"}'::jsonb,'live'),
('language-bank:deny_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The suspect did not ____ being at the scene, but he insisted that he had not taken anything.","acceptedAnswers":["deny"],"distractors":[{"text":"regret","reason":"Fits grammatically, but regret means feel sorry; the but-clause is about what he says he did."},{"text":"forget","reason":"Fits grammatically, but forget means fail to remember, which does not fit a suspect who insisted on a version of events."},{"text":"mind","reason":"Fits grammatically, but mind means be bothered by it, but the but-clause is about what he says he did."}],"linkedVocabularyIds":["vocab_deny"],"primaryEvidenceTargetId":"vocab_deny","languageBankContextId":"deny_ctx_6"}'::jsonb,'live'),
('language-bank:permit_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Our flexible timetable will ____ you to study at your own pace.","acceptedAnswers":["permit"],"distractors":[{"text":"oblige","reason":"Fits grammatically, but oblige means force you, which contradicts flexible and at your own pace."},{"text":"advise","reason":"Fits grammatically, but advise means suggest what to do, but the sentence says what the timetable makes possible."},{"text":"expect","reason":"Fits grammatically, but expect means believe or require you to do it, which does not fit a flexible timetable."}],"linkedVocabularyIds":["vocab_permit"],"primaryEvidenceTargetId":"vocab_permit","languageBankContextId":"permit_ctx_1"}'::jsonb,'live'),
('language-bank:permit_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The council will not ____ anyone to build on the old playing field, because it is protected land.","acceptedAnswers":["permit"],"distractors":[{"text":"encourage","reason":"Fits grammatically, but encourage means make building more likely, which contradicts protected land."},{"text":"ask","reason":"Fits grammatically, but ask means request, but the council is the one that decides whether building can happen."},{"text":"invite","reason":"Fits grammatically, but invite means welcome people to do it, which contradicts protected land."}],"linkedVocabularyIds":["vocab_permit"],"primaryEvidenceTargetId":"vocab_permit","languageBankContextId":"permit_ctx_2"}'::jsonb,'live'),
('language-bank:permit_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The exam rules do not ____ mobile phones, so students must leave them outside the hall.","acceptedAnswers":["permit"],"distractors":[{"text":"recommend","reason":"Fits grammatically, but recommend means suggest as good, but the rules are about what is allowed in the hall."},{"text":"require","reason":"Fits grammatically, but require would mean students must bring phones, which contradicts leaving them outside."},{"text":"supply","reason":"Fits grammatically, but supply means provide phones, but the rules are about what students may bring."}],"linkedVocabularyIds":["vocab_permit"],"primaryEvidenceTargetId":"vocab_permit","languageBankContextId":"permit_ctx_3"}'::jsonb,'live'),
('language-bank:permit_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Would you ____ your children to stay out until midnight on a school night?","acceptedAnswers":["permit"],"distractors":[{"text":"expect","reason":"Fits grammatically, but expect means think they will, whereas the question is whether parents would allow it."},{"text":"advise","reason":"Fits grammatically, but advise means suggest it is a good idea, which does not fit a question about allowing a late night."},{"text":"force","reason":"Fits grammatically, but force means make them do it, while the question is whether parents would let them."}],"linkedVocabularyIds":["vocab_permit"],"primaryEvidenceTargetId":"vocab_permit","languageBankContextId":"permit_ctx_4"}'::jsonb,'live'),
('language-bank:permit_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"A teacher cannot ____ students to copy each other’s answers in an assessment.","acceptedAnswers":["permit"],"distractors":[{"text":"help","reason":"Fits grammatically, but help means assist, but the sentence is about what the rules allow."},{"text":"teach","reason":"Fits grammatically, but teach means show how to do something, not allow it."},{"text":"invite","reason":"Fits grammatically, but invite means ask or welcome them to do it, which is stronger than allowing it."}],"linkedVocabularyIds":["vocab_permit"],"primaryEvidenceTargetId":"vocab_permit","languageBankContextId":"permit_ctx_5"}'::jsonb,'live'),
('language-bank:permit_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The new software will ____ teachers to share lessons with parents from any device.","acceptedAnswers":["permit"],"distractors":[{"text":"require","reason":"Fits grammatically, but require would mean teachers must share lessons, whereas the software makes it possible."},{"text":"remind","reason":"Fits grammatically, but remind means help them remember to do it, not make it possible."},{"text":"advise","reason":"Fits grammatically, but advise means recommend, which does not describe what software makes possible."}],"linkedVocabularyIds":["vocab_permit"],"primaryEvidenceTargetId":"vocab_permit","languageBankContextId":"permit_ctx_6"}'::jsonb,'live'),
('language-bank:arrange_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Please ____ a time that suits everyone so that we can all meet on Saturday.","acceptedAnswers":["arrange"],"distractors":[{"text":"prepare","reason":"Fits grammatically, but prepare means get ready, but a time is fixed by agreement, not prepared."},{"text":"hold","reason":"Fits grammatically, but hold means keep or have; the sentence asks for a time to be agreed."},{"text":"allow","reason":"Fits grammatically, but allow means permit; the sentence asks someone to set a time."}],"linkedVocabularyIds":["vocab_arrange"],"primaryEvidenceTargetId":"vocab_arrange","languageBankContextId":"arrange_ctx_1"}'::jsonb,'live'),
('language-bank:arrange_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"My uncle has offered to ____ transport to the airport for the whole team.","acceptedAnswers":["arrange"],"distractors":[{"text":"prepare","reason":"Fits grammatically, but prepare means get ready, but transport is organised, not prepared like a meal."},{"text":"repair","reason":"Fits grammatically, but repair means fix something broken, whereas the offer is to organise a ride."},{"text":"collect","reason":"Fits grammatically, but collect means pick up, but transport is the thing to be organised, not collected."}],"linkedVocabularyIds":["vocab_arrange"],"primaryEvidenceTargetId":"vocab_arrange","languageBankContextId":"arrange_ctx_2"}'::jsonb,'live'),
('language-bank:arrange_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"We need to ____ a babysitter before we can go out on Friday evening.","acceptedAnswers":["arrange"],"distractors":[{"text":"order","reason":"Fits grammatically, but order means request goods or food, not organise for a person to come."},{"text":"prepare","reason":"Fits grammatically, but prepare means get ready; a babysitter has to be organised, not prepared."},{"text":"train","reason":"Fits grammatically, but train means teach a skill, which is not what is needed before going out."}],"linkedVocabularyIds":["vocab_arrange"],"primaryEvidenceTargetId":"vocab_arrange","languageBankContextId":"arrange_ctx_3"}'::jsonb,'live'),
('language-bank:arrange_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The band’s manager plans to ____ a short tour of five cities in the spring.","acceptedAnswers":["arrange"],"distractors":[{"text":"produce","reason":"Fits grammatically, but produce means make a product, whereas a manager plans and books the tour."},{"text":"follow","reason":"Fits grammatically, but follow means go after, which does not describe setting up a tour."},{"text":"repair","reason":"Fits grammatically, but repair means fix something broken, not plan a tour."}],"linkedVocabularyIds":["vocab_arrange"],"primaryEvidenceTargetId":"vocab_arrange","languageBankContextId":"arrange_ctx_4"}'::jsonb,'live'),
('language-bank:arrange_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"It takes a lot of time to ____ a school trip for two hundred students.","acceptedAnswers":["arrange"],"distractors":[{"text":"accompany","reason":"Fits grammatically, but accompany means go along with, but the sentence is about the work of organising before the trip."},{"text":"attend","reason":"Fits grammatically, but attend means go to; the work described happens before the trip."},{"text":"enjoy","reason":"Fits grammatically, but enjoy means take pleasure in, which does not explain taking a lot of time for two hundred students."}],"linkedVocabularyIds":["vocab_arrange"],"primaryEvidenceTargetId":"vocab_arrange","languageBankContextId":"arrange_ctx_5"}'::jsonb,'live'),
('language-bank:arrange_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"She will ____ to meet us at the station at six, so please wait for her.","acceptedAnswers":["arrange"],"distractors":[{"text":"hope","reason":"Fits grammatically, but hope means wish, which is weaker than the plan the sentence says to wait for."},{"text":"pretend","reason":"Fits grammatically, but pretend means act as if something is true, which does not make a plan to wait for."},{"text":"forget","reason":"Fits grammatically, but forget means fail to remember, which contradicts so please wait for her."}],"linkedVocabularyIds":["vocab_arrange"],"primaryEvidenceTargetId":"vocab_arrange","languageBankContextId":"arrange_ctx_6"}'::jsonb,'live'),
('language-bank:urge_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Doctors strongly ____ patients to take up gentle exercise because the benefits are so large, though the choice is always theirs.","acceptedAnswers":["urge"],"distractors":[{"text":"order","reason":"Fits grammatically, but order means command, but the choice is always theirs says the doctors do not command."},{"text":"warn","reason":"Fits grammatically, but warn means tell people about a danger, but the sentence is about the benefits of exercise."},{"text":"require","reason":"Fits grammatically, but require means make it necessary, but the choice is always theirs says it is not necessary."}],"linkedVocabularyIds":["vocab_urge"],"primaryEvidenceTargetId":"vocab_urge","languageBankContextId":"urge_ctx_1"}'::jsonb,'live'),
('language-bank:urge_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Friends who live here ____ new students to try the local food, which is cheap, delicious and unlike anything most newcomers have tasted.","acceptedAnswers":["urge"],"distractors":[{"text":"warn","reason":"Fits grammatically, but warn means tell people about a danger, but cheap and delicious describes a benefit."},{"text":"remind","reason":"Fits grammatically, but remind means help people remember something they already know, but the food is new to most newcomers."},{"text":"order","reason":"Fits grammatically, but order means command, and friends have no authority to command new students."}],"linkedVocabularyIds":["vocab_urge"],"primaryEvidenceTargetId":"vocab_urge","languageBankContextId":"urge_ctx_2"}'::jsonb,'live'),
('language-bank:urge_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Experts ____ schools to teach financial skills earlier, but they cannot make any school do it, and so far none has agreed.","acceptedAnswers":["urge"],"distractors":[{"text":"force","reason":"Fits grammatically, but force contradicts they cannot make any school do it."},{"text":"persuade","reason":"Fits grammatically, but persuade means succeed in convincing, but so far none has agreed shows they have not succeeded."},{"text":"pay","reason":"Fits grammatically, but pay means give money for it, but nothing in the sentence says the experts offer any payment."}],"linkedVocabularyIds":["vocab_urge"],"primaryEvidenceTargetId":"vocab_urge","languageBankContextId":"urge_ctx_3"}'::jsonb,'live'),
('language-bank:urge_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The charity, which has no authority over ministers, continues to ____ the government to increase funding for youth sport, so far without success.","acceptedAnswers":["urge"],"distractors":[{"text":"force","reason":"Fits grammatically, but force contradicts has no authority over ministers."},{"text":"persuade","reason":"Fits grammatically, but persuade means succeed in convincing, but so far without success shows the government has not been convinced."},{"text":"oblige","reason":"Fits grammatically, but oblige means make someone legally or morally bound, which a charity with no authority cannot do."}],"linkedVocabularyIds":["vocab_urge"],"primaryEvidenceTargetId":"vocab_urge","languageBankContextId":"urge_ctx_4"}'::jsonb,'live'),
('language-bank:urge_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Environmental groups ____ governments to cut emissions faster, although they have no power to make them.","acceptedAnswers":["urge"],"distractors":[{"text":"order","reason":"Fits grammatically, but order contradicts they have no power to make them."},{"text":"force","reason":"Fits grammatically, but force contradicts they have no power to make them."},{"text":"compel","reason":"Fits grammatically, but compel means make someone do something, which contradicts they have no power to make them."}],"linkedVocabularyIds":["vocab_urge"],"primaryEvidenceTargetId":"vocab_urge","languageBankContextId":"urge_ctx_5"}'::jsonb,'live'),
('language-bank:urge_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her parents ____ her to apply for the scholarship, but she has not decided yet and they say the choice is hers.","acceptedAnswers":["urge"],"distractors":[{"text":"force","reason":"Fits grammatically, but force contradicts they say the choice is hers."},{"text":"persuade","reason":"Fits grammatically, but persuade means succeed in convincing her, but she has not decided yet shows they have not succeeded."},{"text":"dare","reason":"Fits grammatically, but dare means challenge someone to do something risky, but applying for a scholarship is not a dare."}],"linkedVocabularyIds":["vocab_urge"],"primaryEvidenceTargetId":"vocab_urge","languageBankContextId":"urge_ctx_6"}'::jsonb,'live'),
('language-bank:recommend_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"My dentist has just retired, so I am asking my colleagues to ____ someone they have been happy with.","acceptedAnswers":["recommend"],"distractors":[{"text":"visit","reason":"Fits grammatically, but visit means go and see someone, but the speaker is asking for a name to try."},{"text":"employ","reason":"Fits grammatically, but employ means give someone a job, but a patient looks for a dentist to treat them."},{"text":"interview","reason":"Fits grammatically, but interview means ask questions to judge someone, but the colleagues are asked to give a name from their own experience."}],"linkedVocabularyIds":["vocab_recommend"],"primaryEvidenceTargetId":"vocab_recommend","languageBankContextId":"recommend_ctx_1"}'::jsonb,'live'),
('language-bank:recommend_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"I would highly ____ the new science museum; my whole class thought it was brilliant.","acceptedAnswers":["recommend"],"distractors":[{"text":"announce","reason":"Fits grammatically, but announce means tell people publicly that something is happening, not say it is worth visiting."},{"text":"advertise","reason":"Fits grammatically, but advertise means promote publicly, whereas the speaker is sharing a personal opinion."},{"text":"admire","reason":"Fits grammatically, but admire means feel respect for it, but the sentence is about advising others to go."}],"linkedVocabularyIds":["vocab_recommend"],"primaryEvidenceTargetId":"vocab_recommend","languageBankContextId":"recommend_ctx_2"}'::jsonb,'live'),
('language-bank:recommend_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The doctor will ____ that you rest for at least three days.","acceptedAnswers":["recommend"],"distractors":[{"text":"promise","reason":"Fits grammatically, but promise means give a personal guarantee, but a doctor gives advice about what you should do."},{"text":"predict","reason":"Fits grammatically, but predict means say what will happen, not what you should do."},{"text":"prescribe","reason":"Fits grammatically, but prescribe is used for medicine; here the doctor is giving advice about resting."}],"linkedVocabularyIds":["vocab_recommend"],"primaryEvidenceTargetId":"vocab_recommend","languageBankContextId":"recommend_ctx_3"}'::jsonb,'live'),
('language-bank:recommend_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Teachers often ____ reading a little every day as a way to build vocabulary.","acceptedAnswers":["recommend"],"distractors":[{"text":"appreciate","reason":"Fits grammatically, but appreciate means value it, but the sentence is about advice teachers give to students."},{"text":"practise","reason":"Fits grammatically, but practise means do it for improvement, whereas the teachers are advising others to do it."},{"text":"require","reason":"Fits grammatically, but require means make it necessary, which is stronger than often suggesting it."}],"linkedVocabularyIds":["vocab_recommend"],"primaryEvidenceTargetId":"vocab_recommend","languageBankContextId":"recommend_ctx_4"}'::jsonb,'live'),
('language-bank:recommend_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Whenever tourists ask where to eat, I ____ my cousin’s bakery because the cheese bread there is wonderful.","acceptedAnswers":["recommend"],"distractors":[{"text":"visit","reason":"Fits grammatically, but visit means go there yourself, but the tourists are the ones who need advice about where to go."},{"text":"review","reason":"Fits grammatically, but review means write or give a formal opinion, whereas the sentence is about what you tell people who ask."},{"text":"compliment","reason":"Fits grammatically, but compliment means praise a person or place to their face, which is not what you tell tourists who ask where to eat."}],"linkedVocabularyIds":["vocab_recommend"],"primaryEvidenceTargetId":"vocab_recommend","languageBankContextId":"recommend_ctx_5"}'::jsonb,'live'),
('language-bank:recommend_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Both coaches ____ that new players wear shin pads in their first session, but it is not compulsory.","acceptedAnswers":["recommend"],"distractors":[{"text":"require","reason":"Fits grammatically, but require contradicts it is not compulsory."},{"text":"insist","reason":"Fits grammatically, but insist means say strongly that it must happen, which contradicts it is not compulsory."},{"text":"guarantee","reason":"Fits grammatically, but guarantee means promise it will happen, which contradicts it is not compulsory."}],"linkedVocabularyIds":["vocab_recommend"],"primaryEvidenceTargetId":"vocab_recommend","languageBankContextId":"recommend_ctx_6"}'::jsonb,'live'),
('language-bank:demand_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Marathon training can ____ patience, discipline and a great deal of time.","acceptedAnswers":["demand"],"distractors":[{"text":"deserve","reason":"Fits grammatically, but deserve means be worthy of, but the sentence lists what training needs from the runner."},{"text":"reward","reason":"Fits grammatically, but reward means give something back, whereas the sentence lists what training asks of you."},{"text":"teach","reason":"Fits grammatically, but teach means give knowledge; the sentence lists what training takes from the runner."}],"linkedVocabularyIds":["vocab_demand"],"primaryEvidenceTargetId":"vocab_demand","languageBankContextId":"demand_ctx_1"}'::jsonb,'live'),
('language-bank:demand_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Learning two languages at once will ____ a lot of concentration.","acceptedAnswers":["demand"],"distractors":[{"text":"improve","reason":"Fits grammatically, but improve would mean make concentration better, but the sentence describes what the task takes from you."},{"text":"strengthen","reason":"Fits grammatically, but strengthen means build up concentration, whereas the sentence describes what is needed."},{"text":"spare","reason":"Fits grammatically, but spare means have extra, which is the opposite of needing a lot."}],"linkedVocabularyIds":["vocab_demand"],"primaryEvidenceTargetId":"vocab_demand","languageBankContextId":"demand_ctx_2"}'::jsonb,'live'),
('language-bank:demand_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Looking after three young children can ____ all of your energy by the end of the day.","acceptedAnswers":["demand"],"distractors":[{"text":"restore","reason":"Fits grammatically, but restore means give energy back, but by the end of the day shows it is used up."},{"text":"produce","reason":"Fits grammatically, but produce means make energy, which is the opposite of using it up."},{"text":"save","reason":"Fits grammatically, but save means keep for later, which does not fit using up energy."}],"linkedVocabularyIds":["vocab_demand"],"primaryEvidenceTargetId":"vocab_demand","languageBankContextId":"demand_ctx_3"}'::jsonb,'live'),
('language-bank:demand_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Elite sport tends to ____ early mornings and very long hours of training.","acceptedAnswers":["demand"],"distractors":[{"text":"reward","reason":"Fits grammatically, but reward means give a benefit back, but the sentence lists what the sport asks of athletes."},{"text":"welcome","reason":"Fits grammatically, but welcome means greet gladly, whereas the sentence is about what the sport asks for."},{"text":"prevent","reason":"Fits grammatically, but prevent means stop something happening, which contradicts long hours of training."}],"linkedVocabularyIds":["vocab_demand"],"primaryEvidenceTargetId":"vocab_demand","languageBankContextId":"demand_ctx_4"}'::jsonb,'live'),
('language-bank:demand_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Becoming a good violinist can ____ years of daily practice and a great deal of patience.","acceptedAnswers":["demand"],"distractors":[{"text":"offer","reason":"Fits grammatically, but offer means give, but the sentence lists what the learner has to give."},{"text":"deserve","reason":"Fits grammatically, but deserve means be worthy of, but the sentence lists what is needed to become good."},{"text":"produce","reason":"Fits grammatically, but produce means make, whereas the sentence is about what becoming a violinist asks of you."}],"linkedVocabularyIds":["vocab_demand"],"primaryEvidenceTargetId":"vocab_demand","languageBankContextId":"demand_ctx_5"}'::jsonb,'live'),
('language-bank:demand_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The new course will ____ a high level of English from every applicant.","acceptedAnswers":["demand"],"distractors":[{"text":"provide","reason":"Fits grammatically, but provide means give, but from every applicant shows it is something asked of them."},{"text":"develop","reason":"Fits grammatically, but develop means build up, but from every applicant shows it is asked for at the start."},{"text":"impress","reason":"Fits grammatically, but impress means make someone admire; the sentence is about what the course asks of applicants."}],"linkedVocabularyIds":["vocab_demand"],"primaryEvidenceTargetId":"vocab_demand","languageBankContextId":"demand_ctx_6"}'::jsonb,'live'),
('language-bank:threaten_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"A serious knee injury could ____ her place in the national squad.","acceptedAnswers":["threaten"],"distractors":[{"text":"strengthen","reason":"Fits grammatically, but strengthen means make her place more secure, which is the opposite of what a serious injury does."},{"text":"defend","reason":"Fits grammatically, but defend means protect, whereas an injury is the danger itself."},{"text":"justify","reason":"Fits grammatically, but justify means give a good reason for, but an injury is a risk, not a reason."}],"linkedVocabularyIds":["vocab_threaten"],"primaryEvidenceTargetId":"vocab_threaten","languageBankContextId":"threaten_ctx_1"}'::jsonb,'live'),
('language-bank:threaten_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Poor funding may ____ the future of the community football club.","acceptedAnswers":["threaten"],"distractors":[{"text":"guarantee","reason":"Fits grammatically, but guarantee means make certain, which is the opposite of what poor funding does."},{"text":"plan","reason":"Fits grammatically, but plan means prepare, but poor funding is a risk to the club, not a plan for it."},{"text":"predict","reason":"Fits grammatically, but predict means say what will happen, but poor funding itself is the cause of the risk."}],"linkedVocabularyIds":["vocab_threaten"],"primaryEvidenceTargetId":"vocab_threaten","languageBankContextId":"threaten_ctx_2"}'::jsonb,'live'),
('language-bank:threaten_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The coach will ____ to drop any player who arrives late again.","acceptedAnswers":["threaten"],"distractors":[{"text":"refuse","reason":"Fits grammatically, but refuse to drop would mean he will not do it, which removes the warning."},{"text":"offer","reason":"Fits grammatically, but offer is a positive gesture, but dropping a player is a punishment."},{"text":"hesitate","reason":"Fits grammatically, but hesitate to drop would mean he is unwilling, which is not a warning to late players."}],"linkedVocabularyIds":["vocab_threaten"],"primaryEvidenceTargetId":"vocab_threaten","languageBankContextId":"threaten_ctx_3"}'::jsonb,'live'),
('language-bank:threaten_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Heavy pollution continues to ____ the survival of rare birds in the area.","acceptedAnswers":["threaten"],"distractors":[{"text":"protect","reason":"Fits grammatically, but protect means keep safe, the opposite of what heavy pollution does."},{"text":"improve","reason":"Fits grammatically, but improve means make better, which does not fit heavy pollution."},{"text":"safeguard","reason":"Fits grammatically, but safeguard means keep safe, but heavy pollution is the danger itself."}],"linkedVocabularyIds":["vocab_threaten"],"primaryEvidenceTargetId":"vocab_threaten","languageBankContextId":"threaten_ctx_4"}'::jsonb,'live'),
('language-bank:threaten_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Dark storm clouds seemed to ____ the outdoor final, and officials began to talk about moving the match indoors.","acceptedAnswers":["threaten"],"distractors":[{"text":"cover","reason":"Fits grammatically, but cover means spread over something, but officials talking about moving the match shows the clouds were a danger to it."},{"text":"surround","reason":"Fits grammatically, but surround means be on every side of it, but officials talking about moving the match shows the clouds were a danger to it."},{"text":"soak","reason":"Fits grammatically, but soak means make completely wet, but seemed to shows the clouds had not yet reached the match; they were a risk to it."}],"linkedVocabularyIds":["vocab_threaten"],"primaryEvidenceTargetId":"vocab_threaten","languageBankContextId":"threaten_ctx_5"}'::jsonb,'live'),
('language-bank:threaten_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Union leaders say the new rules could ____ the jobs of thousands of factory workers, and they want the government to think again.","acceptedAnswers":["threaten"],"distractors":[{"text":"reward","reason":"Fits grammatically, but reward means give something back for good work, but want the government to think again shows the unions see the rules as harmful."},{"text":"regulate","reason":"Fits grammatically, but regulate means control by rules, but the unions are worried about the jobs themselves, not how they are controlled."},{"text":"define","reason":"Fits grammatically, but define means state exactly what something is, which would not make unions ask the government to think again."}],"linkedVocabularyIds":["vocab_threaten"],"primaryEvidenceTargetId":"vocab_threaten","languageBankContextId":"threaten_ctx_6"}'::jsonb,'live'),
('language-bank:resent_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He began to ____ being left out of the team, even though he had trained hard all season.","acceptedAnswers":["resent"],"distractors":[{"text":"regret","reason":"Fits grammatically, but regret means feel sorry about something he did, but the sentence is about unfair treatment."},{"text":"deserve","reason":"Fits grammatically, but deserve would mean he was worthy of being left out, which contradicts trained hard."},{"text":"expect","reason":"Fits grammatically, but expect means think it will happen, which does not show his anger about trained hard."}],"linkedVocabularyIds":["vocab_resent"],"primaryEvidenceTargetId":"vocab_resent","languageBankContextId":"resent_ctx_1"}'::jsonb,'live'),
('language-bank:resent_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Many workers ____ being told to stay late without extra pay.","acceptedAnswers":["resent"],"distractors":[{"text":"fear","reason":"Fits grammatically, but fear means be afraid it will happen, but without extra pay explains an unfair order, not a risk."},{"text":"expect","reason":"Fits grammatically, but expect means think it will happen, which does not show the feeling about unfair treatment."},{"text":"avoid","reason":"Fits grammatically, but avoid means keep away from it, but they are told to stay, so it is not their choice."}],"linkedVocabularyIds":["vocab_resent"],"primaryEvidenceTargetId":"vocab_resent","languageBankContextId":"resent_ctx_2"}'::jsonb,'live'),
('language-bank:resent_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Some players ____ the coach for choosing younger teammates, and they refuse to speak to him.","acceptedAnswers":["resent"],"distractors":[{"text":"forgive","reason":"Fits grammatically, but forgive would mean they no longer blame him, which contradicts refuse to speak to him."},{"text":"thank","reason":"Fits grammatically, but thank means show gratitude, which contradicts refuse to speak to him."},{"text":"congratulate","reason":"Fits grammatically, but congratulate means praise, which contradicts refuse to speak to him."}],"linkedVocabularyIds":["vocab_resent"],"primaryEvidenceTargetId":"vocab_resent","languageBankContextId":"resent_ctx_3"}'::jsonb,'live'),
('language-bank:resent_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Last year the manager changed everyone’s shifts without warning, and many staff still ____ it.","acceptedAnswers":["resent"],"distractors":[{"text":"regret","reason":"Fits grammatically, but regret means feel sorry about something you did yourself, but the staff did not make the change."},{"text":"dread","reason":"Fits grammatically, but dread means fear something that has not happened yet, but the change happened last year."},{"text":"mourn","reason":"Fits grammatically, but mourn means feel deep sadness over a loss, whereas the staff feel anger about an unfair change."}],"linkedVocabularyIds":["vocab_resent"],"primaryEvidenceTargetId":"vocab_resent","languageBankContextId":"resent_ctx_4"}'::jsonb,'live'),
('language-bank:resent_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"They ____ the extra homework, because they thought it was unfair to set it on a Friday.","acceptedAnswers":["resent"],"distractors":[{"text":"avoid","reason":"Fits grammatically, but avoid means keep away from it, but the sentence is about how they felt about it."},{"text":"ignore","reason":"Fits grammatically, but ignore means pay no attention, whereas the sentence gives their feeling that it was unfair."},{"text":"question","reason":"Fits grammatically, but question means ask about, but the sentence gives their angry feeling of unfairness."}],"linkedVocabularyIds":["vocab_resent"],"primaryEvidenceTargetId":"vocab_resent","languageBankContextId":"resent_ctx_5"}'::jsonb,'live'),
('language-bank:resent_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"She felt hurt that the coach had picked someone else, and although she never said a word to anyone, she could not help but ____ the new girl’s place in the team.","acceptedAnswers":["resent"],"distractors":[{"text":"welcome","reason":"Fits grammatically, but welcome means be glad about it, which contradicts felt hurt."},{"text":"discuss","reason":"Fits grammatically, but discuss means talk about it with others, which contradicts although she never said a word to anyone."},{"text":"mention","reason":"Fits grammatically, but mention means say something about it, which contradicts although she never said a word to anyone."}],"linkedVocabularyIds":["vocab_resent"],"primaryEvidenceTargetId":"vocab_resent","languageBankContextId":"resent_ctx_6"}'::jsonb,'live'),
('language-bank:regret_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He told me that he will always ____ his own decision to leave school so early and often wishes he had stayed.","acceptedAnswers":["regret"],"distractors":[{"text":"resent","reason":"Fits grammatically, but resent means feel angry about something unfair, but the sentence is about his own decision and his wish that he had stayed."},{"text":"defend","reason":"Fits grammatically, but defend means argue in support of it, but wishes he had stayed shows he does not support the decision."},{"text":"forget","reason":"Fits grammatically, but forget contradicts will always and often wishes he had stayed."}],"linkedVocabularyIds":["vocab_regret"],"primaryEvidenceTargetId":"vocab_regret","languageBankContextId":"regret_ctx_1"}'::jsonb,'live'),
('language-bank:regret_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"We ____ to tell you that your application has not been successful this year.","acceptedAnswers":["regret"],"distractors":[{"text":"decide","reason":"Fits grammatically, but decide to tell you does not fit the formal, sorry tone of a rejection letter."},{"text":"refuse","reason":"Fits grammatically, but refuse to tell you contradicts the fact that the sentence is telling the reader."},{"text":"promise","reason":"Fits grammatically, but promise to tell you does not fit bad news."}],"linkedVocabularyIds":["vocab_regret"],"primaryEvidenceTargetId":"vocab_regret","languageBankContextId":"regret_ctx_2"}'::jsonb,'live'),
('language-bank:regret_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"She did not ____ her decision to change schools; she said she was much happier now.","acceptedAnswers":["regret"],"distractors":[{"text":"explain","reason":"Fits grammatically, but explain means give reasons, but the sentence says she was happier, not that she gave reasons."},{"text":"announce","reason":"Fits grammatically, but announce means tell people publicly, but the second clause is about her feelings afterwards."},{"text":"defend","reason":"Fits grammatically, but defend means argue in support of it, but she says she is happier, which is about her feelings, not an argument she needs to make."}],"linkedVocabularyIds":["vocab_regret"],"primaryEvidenceTargetId":"vocab_regret","languageBankContextId":"regret_ctx_3"}'::jsonb,'live'),
('language-bank:regret_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Looking back, many retired athletes ____ not spending more time with their families.","acceptedAnswers":["regret"],"distractors":[{"text":"mention","reason":"Fits grammatically, but mention means say briefly, but looking back suggests a feeling, not just a remark."},{"text":"notice","reason":"Fits grammatically, but notice means become aware of, but looking back suggests sadness about a past choice."},{"text":"expect","reason":"Fits grammatically, but expect means think that it will happen, which does not fit looking back."}],"linkedVocabularyIds":["vocab_regret"],"primaryEvidenceTargetId":"vocab_regret","languageBankContextId":"regret_ctx_4"}'::jsonb,'live'),
('language-bank:regret_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"If you leave your revision until the last minute, you will bitterly ____ it on the day of the exam.","acceptedAnswers":["regret"],"distractors":[{"text":"forget","reason":"Fits grammatically, but forget does not combine with bitterly, which signals a strong feeling."},{"text":"repeat","reason":"Fits grammatically, but repeat does not combine with bitterly, which signals a strong feeling."},{"text":"mention","reason":"Fits grammatically, but mention does not combine with bitterly, which signals a strong feeling."}],"linkedVocabularyIds":["vocab_regret"],"primaryEvidenceTargetId":"vocab_regret","languageBankContextId":"regret_ctx_5"}'::jsonb,'live'),
('language-bank:regret_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He apologised for the mistake and said he would always ____ what he had said to his teammate.","acceptedAnswers":["regret"],"distractors":[{"text":"repeat","reason":"Fits grammatically, but repeat contradicts apologised."},{"text":"defend","reason":"Fits grammatically, but defend contradicts apologised."},{"text":"deny","reason":"Fits grammatically, but deny contradicts apologised."}],"linkedVocabularyIds":["vocab_regret"],"primaryEvidenceTargetId":"vocab_regret","languageBankContextId":"regret_ctx_6"}'::jsonb,'live'),
('language-bank:unfamiliar_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Many of the rules in baseball seemed ____ to the exchange students, because none of them had ever watched a game.","acceptedAnswers":["unfamiliar"],"distractors":[{"text":"unfair","reason":"Fits grammatically, but unfair means not treated equally, but none of them had ever watched a game explains lack of experience, not unfairness."},{"text":"unnecessary","reason":"Fits grammatically, but unnecessary means not needed, but the cue is that they had never seen the game."},{"text":"unpopular","reason":"Fits grammatically, but unpopular means disliked by many people, but the cue is that none of them had watched a game."}],"linkedVocabularyIds":["vocab_unfamiliar"],"primaryEvidenceTargetId":"vocab_unfamiliar","languageBankContextId":"unfamiliar_ctx_1"}'::jsonb,'live'),
('language-bank:unfamiliar_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Moving to another country means getting used to ____ food, customs and routines.","acceptedAnswers":["unfamiliar"],"distractors":[{"text":"unhealthy","reason":"Fits grammatically, but unhealthy would describe something bad for you, but the cue is getting used to new things."},{"text":"unreliable","reason":"Fits grammatically, but unreliable means cannot be trusted, which does not fit getting used to new things."},{"text":"unpleasant","reason":"Fits grammatically, but unpleasant means not nice, but the cue is that the things are new to you."}],"linkedVocabularyIds":["vocab_unfamiliar"],"primaryEvidenceTargetId":"vocab_unfamiliar","languageBankContextId":"unfamiliar_ctx_2"}'::jsonb,'live'),
('language-bank:unfamiliar_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"She felt nervous walking into the ____ gym, because she had never been inside it before.","acceptedAnswers":["unfamiliar"],"distractors":[{"text":"unfinished","reason":"Fits grammatically, but unfinished means not completed, but never been inside it before explains why she felt nervous."},{"text":"unsafe","reason":"Fits grammatically, but unsafe means dangerous, but the sentence does not say there is any danger."},{"text":"unpopular","reason":"Fits grammatically, but unpopular means disliked, but the cue is that she had never been inside."}],"linkedVocabularyIds":["vocab_unfamiliar"],"primaryEvidenceTargetId":"vocab_unfamiliar","languageBankContextId":"unfamiliar_ctx_3"}'::jsonb,'live'),
('language-bank:unfamiliar_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The route was ____ to us, so we kept stopping at every junction to check the map.","acceptedAnswers":["unfamiliar"],"distractors":[{"text":"unpleasant","reason":"Fits grammatically, but unpleasant means not nice, but the cue is checking the map because they did not know the way."},{"text":"unlikely","reason":"Fits grammatically, but unlikely means probably not true, which does not fit a route they were walking."},{"text":"unmarked","reason":"Fits grammatically, but unmarked means without signs, and could explain stopping, but to us shows the problem is that they did not know it."}],"linkedVocabularyIds":["vocab_unfamiliar"],"primaryEvidenceTargetId":"vocab_unfamiliar","languageBankContextId":"unfamiliar_ctx_4"}'::jsonb,'live'),
('language-bank:unfamiliar_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Even experienced players can make mistakes when they use ____ equipment for the first time.","acceptedAnswers":["unfamiliar"],"distractors":[{"text":"unattractive","reason":"Fits grammatically, but unattractive means not nice to look at, which does not explain mistakes."},{"text":"unnecessary","reason":"Fits grammatically, but unnecessary means not needed, which does not explain mistakes."},{"text":"unpopular","reason":"Fits grammatically, but unpopular means disliked, but for the first time is the cue that it is new to them."}],"linkedVocabularyIds":["vocab_unfamiliar"],"primaryEvidenceTargetId":"vocab_unfamiliar","languageBankContextId":"unfamiliar_ctx_5"}'::jsonb,'live'),
('language-bank:unfamiliar_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The rules of cricket are completely ____ to anyone who has grown up outside the countries where it is played.","acceptedAnswers":["unfamiliar"],"distractors":[{"text":"unfair","reason":"Fits grammatically, but unfair means not just, but the cue is anyone who has grown up outside."},{"text":"unpopular","reason":"Fits grammatically, but unpopular means disliked, but the cue is lack of experience."},{"text":"unimportant","reason":"Fits grammatically, but unimportant means of little value, but the cue is lack of experience."}],"linkedVocabularyIds":["vocab_unfamiliar"],"primaryEvidenceTargetId":"vocab_unfamiliar","languageBankContextId":"unfamiliar_ctx_6"}'::jsonb,'live'),
('language-bank:racquet_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"She replaced the broken strings on her tennis ____ before the final.","acceptedAnswers":["racquet"],"distractors":[{"text":"bat","reason":"Fits grammatically, but a bat is used in cricket and baseball and has no strings."},{"text":"club","reason":"Fits grammatically, but a club is used in golf and has no strings."},{"text":"paddle","reason":"Fits grammatically, but a paddle is used in table tennis and has no strings."}],"linkedVocabularyIds":["vocab_racquet"],"primaryEvidenceTargetId":"vocab_racquet","languageBankContextId":"racquet_ctx_1"}'::jsonb,'live'),
('language-bank:racquet_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"In badminton, players hit the shuttlecock over the net with a light ____.","acceptedAnswers":["racquet"],"distractors":[{"text":"bat","reason":"Fits grammatically, but a bat is used in sports such as cricket and table tennis, but badminton players use a frame with strings."},{"text":"hockey stick","reason":"Fits grammatically, but a hockey stick is used to hit a ball along the ground, not a shuttlecock over a net."},{"text":"paddle","reason":"Fits grammatically, but a paddle is used for rowing or table tennis, not badminton."}],"linkedVocabularyIds":["vocab_racquet"],"primaryEvidenceTargetId":"vocab_racquet","languageBankContextId":"racquet_ctx_2"}'::jsonb,'live'),
('language-bank:racquet_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He threw his ____ onto the court after missing the final point, snapping two strings, and had to borrow another one.","acceptedAnswers":["racquet"],"distractors":[{"text":"bat","reason":"Fits grammatically, but a bat has no strings to snap."},{"text":"mouthguard","reason":"Fits grammatically, but a mouthguard is worn in the mouth, and has no strings."},{"text":"stick","reason":"Fits grammatically, but a stick has no strings to snap."}],"linkedVocabularyIds":["vocab_racquet"],"primaryEvidenceTargetId":"vocab_racquet","languageBankContextId":"racquet_ctx_3"}'::jsonb,'live'),
('language-bank:racquet_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Squash players usually carry a spare ____ in their bag in case a string snaps.","acceptedAnswers":["racquet"],"distractors":[{"text":"stick","reason":"Fits grammatically, but a stick has no strings."},{"text":"glove","reason":"Fits grammatically, but a glove does not have strings to snap."},{"text":"wristband","reason":"Fits grammatically, but a wristband does not have strings to snap."}],"linkedVocabularyIds":["vocab_racquet"],"primaryEvidenceTargetId":"vocab_racquet","languageBankContextId":"racquet_ctx_4"}'::jsonb,'live'),
('language-bank:racquet_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"A beginner should choose a ____ with a larger strung head, because it makes the ball easier to hit.","acceptedAnswers":["racquet"],"distractors":[{"text":"mallet","reason":"Fits grammatically, but a mallet is used in croquet and has a solid head, not a strung frame."},{"text":"club","reason":"Fits grammatically, but a club has a solid head and no strings."},{"text":"bat","reason":"Fits grammatically, but a bat has a solid surface, not a strung head."}],"linkedVocabularyIds":["vocab_racquet"],"primaryEvidenceTargetId":"vocab_racquet","languageBankContextId":"racquet_ctx_5"}'::jsonb,'live'),
('language-bank:racquet_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The coach showed the children how to hold the ____ so that the strings faced the ball.","acceptedAnswers":["racquet"],"distractors":[{"text":"bat","reason":"Fits grammatically, but a bat has no strings."},{"text":"mallet","reason":"Fits grammatically, but a mallet has no strings."},{"text":"whistle","reason":"Fits grammatically, but a whistle is blown, not held to face a ball."}],"linkedVocabularyIds":["vocab_racquet"],"primaryEvidenceTargetId":"vocab_racquet","languageBankContextId":"racquet_ctx_6"}'::jsonb,'live'),
('language-bank:opponent_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The tennis player shook hands with her ____, who had just beaten her in three sets.","acceptedAnswers":["opponent"],"distractors":[{"text":"referee","reason":"Fits grammatically, but a referee does not play, and the sentence says the person had just beaten her."},{"text":"spectator","reason":"Fits grammatically, but a spectator watches and does not play, and the sentence says the person had just beaten her."},{"text":"partner","reason":"Fits grammatically, but a partner plays on the same side, not against her."}],"linkedVocabularyIds":["vocab_opponent"],"primaryEvidenceTargetId":"vocab_opponent","languageBankContextId":"opponent_ctx_1"}'::jsonb,'live'),
('language-bank:opponent_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Before the game, the captain studied video of the other team’s goalkeeper to find the ____’s weaknesses.","acceptedAnswers":["opponent"],"distractors":[{"text":"coach","reason":"Fits grammatically, but the captain is studying the player on the pitch, not the coach."},{"text":"referee","reason":"Fits grammatically, but the referee is not playing, so there are no weaknesses to exploit in a match."},{"text":"teammate","reason":"Fits grammatically, but a teammate is on the captain’s own side, but the video is of the other team’s goalkeeper."}],"linkedVocabularyIds":["vocab_opponent"],"primaryEvidenceTargetId":"vocab_opponent","languageBankContextId":"opponent_ctx_2"}'::jsonb,'live'),
('language-bank:opponent_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"In doubles, you must communicate clearly with your partner, but never give your ____ any hint about your plan.","acceptedAnswers":["opponent"],"distractors":[{"text":"teammate","reason":"Fits grammatically, but a teammate is on your side, so you would share your plan, not hide it."},{"text":"coach","reason":"Fits grammatically, but a coach is on your side, so you would share the plan."},{"text":"supporter","reason":"Fits grammatically, but a supporter is on your side, so you would not need to hide the plan."}],"linkedVocabularyIds":["vocab_opponent"],"primaryEvidenceTargetId":"vocab_opponent","languageBankContextId":"opponent_ctx_3"}'::jsonb,'live'),
('language-bank:opponent_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Chess players must think about the next move that their ____ is likely to make.","acceptedAnswers":["opponent"],"distractors":[{"text":"coach","reason":"Fits grammatically, but a coach advises from outside the game and does not make moves."},{"text":"partner","reason":"Fits grammatically, but a partner would be working with them, but chess is played against another person."},{"text":"judge","reason":"Fits grammatically, but a judge scores or rules on a game and does not make moves in it."}],"linkedVocabularyIds":["vocab_opponent"],"primaryEvidenceTargetId":"vocab_opponent","languageBankContextId":"opponent_ctx_4"}'::jsonb,'live'),
('language-bank:opponent_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"A good boxer respects every ____, even one who has lost his last five fights.","acceptedAnswers":["opponent"],"distractors":[{"text":"fan","reason":"Fits grammatically, but a fan supports a boxer and does not fight him."},{"text":"trainer","reason":"Fits grammatically, but a trainer helps a boxer prepare and does not fight him."},{"text":"referee","reason":"Fits grammatically, but a referee controls the fight and has not lost five fights."}],"linkedVocabularyIds":["vocab_opponent"],"primaryEvidenceTargetId":"vocab_opponent","languageBankContextId":"opponent_ctx_5"}'::jsonb,'live'),
('language-bank:opponent_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"When two teams meet, each team is the other’s ____, but off the pitch the players are often friends.","acceptedAnswers":["opponent"],"distractors":[{"text":"supporter","reason":"Fits grammatically, but a supporter would be on the team’s side, which contradicts two teams meeting to compete."},{"text":"partner","reason":"Fits grammatically, but a partner is on the same side, which contradicts two teams meeting to compete."},{"text":"manager","reason":"Fits grammatically, but a manager belongs to the team, not the other side."}],"linkedVocabularyIds":["vocab_opponent"],"primaryEvidenceTargetId":"vocab_opponent","languageBankContextId":"opponent_ctx_6"}'::jsonb,'live'),
('language-bank:intense_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Players faced ____ pressure in the final minutes, with the score level and the whole crowd roaring.","acceptedAnswers":["intense"],"distractors":[{"text":"extensive","reason":"Fits grammatically, but extensive means covering a large area or amount, not strength of feeling."},{"text":"instant","reason":"Fits grammatically, but instant means happening immediately, not strong."},{"text":"tense","reason":"Fits grammatically, but tense describes a situation or a person, but pressure is not described as tense."}],"linkedVocabularyIds":["vocab_intense"],"primaryEvidenceTargetId":"vocab_intense","languageBankContextId":"intense_ctx_1"}'::jsonb,'live'),
('language-bank:intense_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The sun was so ____ that the runners had to stop for water every few minutes.","acceptedAnswers":["intense"],"distractors":[{"text":"extensive","reason":"Fits grammatically, but extensive means covering a large area, not very strong."},{"text":"intensive","reason":"Fits grammatically, but intensive means concentrated over a short time (an intensive course), not very strong heat."},{"text":"instant","reason":"Fits grammatically, but instant means immediate, not strong."}],"linkedVocabularyIds":["vocab_intense"],"primaryEvidenceTargetId":"vocab_intense","languageBankContextId":"intense_ctx_2"}'::jsonb,'live'),
('language-bank:intense_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"She trained with ____ concentration, never once looking at the clock.","acceptedAnswers":["intense"],"distractors":[{"text":"extensive","reason":"Fits grammatically, but extensive means covering a large area, not very strong focus."},{"text":"intentional","reason":"Fits grammatically, but intentional means done on purpose, not very strong focus."},{"text":"sudden","reason":"Fits grammatically, but sudden means happening quickly and unexpectedly, not very strong focus."}],"linkedVocabularyIds":["vocab_intense"],"primaryEvidenceTargetId":"vocab_intense","languageBankContextId":"intense_ctx_3"}'::jsonb,'live'),
('language-bank:intense_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The rivalry between the two schools is so ____ that even friendly matches feel like finals.","acceptedAnswers":["intense"],"distractors":[{"text":"intensive","reason":"Fits grammatically, but intensive means concentrated over a short time (an intensive course), not very strong feeling."},{"text":"internal","reason":"Fits grammatically, but internal means inside the group, not very strong feeling."},{"text":"secret","reason":"Fits grammatically, but secret means hidden from others, but even friendly matches feel like finals shows the rivalry is open and strong."}],"linkedVocabularyIds":["vocab_intense"],"primaryEvidenceTargetId":"vocab_intense","languageBankContextId":"intense_ctx_4"}'::jsonb,'live'),
('language-bank:intense_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"After weeks of ____ heat, the farmers began to worry about their crops.","acceptedAnswers":["intense"],"distractors":[{"text":"instant","reason":"Fits grammatically, but instant means immediate, but weeks of describes something long-lasting."},{"text":"intensive","reason":"Fits grammatically, but intensive describes concentrated effort, not weather."},{"text":"immediate","reason":"Fits grammatically, but immediate means happening now, but weeks of describes something long-lasting."}],"linkedVocabularyIds":["vocab_intense"],"primaryEvidenceTargetId":"vocab_intense","languageBankContextId":"intense_ctx_5"}'::jsonb,'live'),
('language-bank:intense_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The coach’s ____ stare made the young players realise how serious the match was.","acceptedAnswers":["intense"],"distractors":[{"text":"intensive","reason":"Fits grammatically, but intensive describes concentrated effort, not how a look feels."},{"text":"internal","reason":"Fits grammatically, but internal means inside a group or place, which does not describe how strong a look is."},{"text":"immediate","reason":"Fits grammatically, but immediate means happening straight away, which describes timing, not how strong the look is."}],"linkedVocabularyIds":["vocab_intense"],"primaryEvidenceTargetId":"vocab_intense","languageBankContextId":"intense_ctx_6"}'::jsonb,'live'),
('language-bank:tournament_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Sixteen schools entered the knockout ____, and only the winners of each match went through to the next round.","acceptedAnswers":["tournament"],"distractors":[{"text":"league","reason":"Fits grammatically, but a league has teams play each other repeatedly over a season, not in knockout rounds."},{"text":"season","reason":"Fits grammatically, but a season is a period of the year, not a single knockout event."},{"text":"exhibition","reason":"Fits grammatically, but an exhibition is a public display or friendly game, not a series of knockout matches."}],"linkedVocabularyIds":["vocab_tournament"],"primaryEvidenceTargetId":"vocab_tournament","languageBankContextId":"tournament_ctx_1"}'::jsonb,'live'),
('language-bank:tournament_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He scored the winning goal in the semi-final of the ____, which his team went on to win.","acceptedAnswers":["tournament"],"distractors":[{"text":"league","reason":"Fits grammatically, but a league does not normally have a semi-final."},{"text":"season","reason":"Fits grammatically, but a season is a period of time, and a semi-final belongs to one event."},{"text":"training camp","reason":"Fits grammatically, but a training camp is for preparing players, and the sentence describes a competition with a winner."}],"linkedVocabularyIds":["vocab_tournament"],"primaryEvidenceTargetId":"vocab_tournament","languageBankContextId":"tournament_ctx_2"}'::jsonb,'live'),
('language-bank:tournament_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The school is hosting a one-day ____ for six local teams, with the final at four o’clock.","acceptedAnswers":["tournament"],"distractors":[{"text":"training camp","reason":"Fits grammatically, but a training camp is for preparing players and does not normally end with a final between teams."},{"text":"workshop","reason":"Fits grammatically, but a workshop is a session for learning, not a competition between teams."},{"text":"league","reason":"Fits grammatically, but a league lasts a whole season, not a single day."}],"linkedVocabularyIds":["vocab_tournament"],"primaryEvidenceTargetId":"vocab_tournament","languageBankContextId":"tournament_ctx_3"}'::jsonb,'live'),
('language-bank:tournament_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Because of heavy rain, the organisers postponed the quarter-finals and semi-finals of the ____ until next weekend.","acceptedAnswers":["tournament"],"distractors":[{"text":"season","reason":"Fits grammatically, but a season is a period of the year, and it is not divided into quarter-finals and semi-finals."},{"text":"series","reason":"Fits grammatically, but a series has matches, but it is not decided by quarter-finals and semi-finals."},{"text":"exhibition","reason":"Fits grammatically, but an exhibition is a public display or friendly game, not a competition with quarter-finals and semi-finals."}],"linkedVocabularyIds":["vocab_tournament"],"primaryEvidenceTargetId":"vocab_tournament","languageBankContextId":"tournament_ctx_4"}'::jsonb,'live'),
('language-bank:tournament_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Players from twelve countries took part in the international ____ in Singapore.","acceptedAnswers":["tournament"],"distractors":[{"text":"festival","reason":"Fits grammatically, but a festival is a celebration, whereas players from twelve countries took part suggests a competition between players."},{"text":"carnival","reason":"Fits grammatically, but a carnival is a street celebration, whereas players from twelve countries took part suggests a competition between players."},{"text":"league","reason":"Fits grammatically, but a league runs over a season in one country, not a single event in Singapore."}],"linkedVocabularyIds":["vocab_tournament"],"primaryEvidenceTargetId":"vocab_tournament","languageBankContextId":"tournament_ctx_5"}'::jsonb,'live'),
('language-bank:tournament_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Our team lost its first match but still reached the final of the ____ by winning all its remaining games.","acceptedAnswers":["tournament"],"distractors":[{"text":"qualifier","reason":"Fits grammatically, but a qualifier is an earlier stage used to decide who enters the main event, not the event with the final."},{"text":"series","reason":"Fits grammatically, but a series has matches, but it does not normally have a final."},{"text":"expedition","reason":"Fits grammatically, but an expedition is a journey, not a competition with a final."}],"linkedVocabularyIds":["vocab_tournament"],"primaryEvidenceTargetId":"vocab_tournament","languageBankContextId":"tournament_ctx_6"}'::jsonb,'live'),
('language-bank:determined_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Even after three defeats, she was ____ to qualify for the national team and refused to give up.","acceptedAnswers":["determined"],"distractors":[{"text":"reluctant","reason":"Fits grammatically, but reluctant means unwilling, which contradicts refused to give up."},{"text":"embarrassed","reason":"Fits grammatically, but embarrassed to qualify would mean she felt awkward about succeeding, which does not fit refused to give up."},{"text":"likely","reason":"Fits grammatically, but likely to qualify means probably will, but refused to give up shows her attitude, not a prediction."}],"linkedVocabularyIds":["vocab_determined"],"primaryEvidenceTargetId":"vocab_determined","languageBankContextId":"determined_ctx_1"}'::jsonb,'live'),
('language-bank:determined_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The team was ____ to win the match despite being two goals behind at half-time.","acceptedAnswers":["determined"],"distractors":[{"text":"bound","reason":"Fits grammatically, but bound to win means certain to, but despite being two goals behind shows a decision, not a prediction."},{"text":"unwilling","reason":"Fits grammatically, but unwilling to win contradicts the idea of fighting back despite being two goals behind."},{"text":"ashamed","reason":"Fits grammatically, but ashamed to win would mean they felt bad about winning, which does not fit despite being two goals behind."}],"linkedVocabularyIds":["vocab_determined"],"primaryEvidenceTargetId":"vocab_determined","languageBankContextId":"determined_ctx_2"}'::jsonb,'live'),
('language-bank:determined_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He showed a ____ effort in the last lap, refusing to slow down even though his legs were aching.","acceptedAnswers":["determined"],"distractors":[{"text":"careless","reason":"Fits grammatically, but careless contradicts refusing to slow down."},{"text":"half-hearted","reason":"Fits grammatically, but half-hearted means without full effort, which contradicts refusing to slow down."},{"text":"gentle","reason":"Fits grammatically, but gentle contradicts refusing to slow down."}],"linkedVocabularyIds":["vocab_determined"],"primaryEvidenceTargetId":"vocab_determined","languageBankContextId":"determined_ctx_3"}'::jsonb,'live'),
('language-bank:determined_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The school record was no accident: although she had little natural talent, the ____ young swimmer had practised every morning for a year.","acceptedAnswers":["determined"],"distractors":[{"text":"gifted","reason":"Fits grammatically, but gifted means naturally talented, which contradicts although she had little natural talent."},{"text":"lucky","reason":"Fits grammatically, but lucky means helped by chance, which contradicts the record was no accident."},{"text":"carefree","reason":"Fits grammatically, but carefree means without worries, which does not fit practising every morning for a year."}],"linkedVocabularyIds":["vocab_determined"],"primaryEvidenceTargetId":"vocab_determined","languageBankContextId":"determined_ctx_4"}'::jsonb,'live'),
('language-bank:determined_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Although the climb was dangerous, the team stayed ____ to reach the summit before dark.","acceptedAnswers":["determined"],"distractors":[{"text":"nervous","reason":"Fits grammatically, but nervous describes fear, but the sentence says they stayed firmly set on reaching the summit."},{"text":"enthusiastic","reason":"Fits grammatically, but enthusiastic means very keen, but the sentence stresses that they stayed firmly set on reaching the summit despite danger."},{"text":"confused","reason":"Fits grammatically, but confused describes not understanding, which does not fit staying set on the summit."}],"linkedVocabularyIds":["vocab_determined"],"primaryEvidenceTargetId":"vocab_determined","languageBankContextId":"determined_ctx_5"}'::jsonb,'live'),
('language-bank:determined_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her ____ attitude impressed the coach, who said she never complained, even after the hardest sessions.","acceptedAnswers":["determined"],"distractors":[{"text":"careless","reason":"Fits grammatically, but careless contradicts never complained and the coach’s praise."},{"text":"indifferent","reason":"Fits grammatically, but indifferent means not caring, which contradicts the coach being impressed."},{"text":"proud","reason":"Fits grammatically, but proud describes feeling pleased with yourself, but the coach praised her attitude to training."}],"linkedVocabularyIds":["vocab_determined"],"primaryEvidenceTargetId":"vocab_determined","languageBankContextId":"determined_ctx_6"}'::jsonb,'live'),
('language-bank:discipline_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Training at five every morning in winter takes real ____, because nobody forces you to keep to the routine.","acceptedAnswers":["discipline"],"distractors":[{"text":"talent","reason":"Fits grammatically, but talent is natural ability, but nobody forces you to keep to the routine points to self-control."},{"text":"fitness","reason":"Fits grammatically, but fitness is physical condition, but nobody forces you to keep to the routine points to self-control."},{"text":"experience","reason":"Fits grammatically, but experience is knowledge from the past, but nobody forces you to keep to the routine points to self-control."}],"linkedVocabularyIds":["vocab_discipline"],"primaryEvidenceTargetId":"vocab_discipline","languageBankContextId":"discipline_ctx_1"}'::jsonb,'live'),
('language-bank:discipline_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Success in a sport depends on talent, but it also depends on the ____ to follow a strict timetable even when you feel tired.","acceptedAnswers":["discipline"],"distractors":[{"text":"flexibility","reason":"Fits grammatically, but flexibility is the ability to change, which is the opposite of following a strict timetable."},{"text":"creativity","reason":"Fits grammatically, but creativity is the ability to produce new ideas, not to follow a fixed timetable."},{"text":"intelligence","reason":"Fits grammatically, but intelligence is the ability to understand, not to follow a fixed timetable."}],"linkedVocabularyIds":["vocab_discipline"],"primaryEvidenceTargetId":"vocab_discipline","languageBankContextId":"discipline_ctx_2"}'::jsonb,'live'),
('language-bank:discipline_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The coach praised the team’s ____ in following the training plan exactly, even when no one was watching.","acceptedAnswers":["discipline"],"distractors":[{"text":"teamwork","reason":"Fits grammatically, but teamwork is working together, but even when no one was watching points to individual self-control."},{"text":"loyalty","reason":"Fits grammatically, but loyalty is staying faithful to people or a team, not following a plan exactly."},{"text":"fitness","reason":"Fits grammatically, but fitness is physical condition, not the self-control to follow a plan exactly."}],"linkedVocabularyIds":["vocab_discipline"],"primaryEvidenceTargetId":"vocab_discipline","languageBankContextId":"discipline_ctx_3"}'::jsonb,'live'),
('language-bank:discipline_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"With a little ____, you can put aside a small amount of money each week even when you are tempted to spend it.","acceptedAnswers":["discipline"],"distractors":[{"text":"luck","reason":"Fits grammatically, but luck is chance, which does not control temptation each week."},{"text":"generosity","reason":"Fits grammatically, but generosity is giving to others, which does not help you put money aside."},{"text":"imagination","reason":"Fits grammatically, but imagination is picturing new things, which does not control temptation each week."}],"linkedVocabularyIds":["vocab_discipline"],"primaryEvidenceTargetId":"vocab_discipline","languageBankContextId":"discipline_ctx_4"}'::jsonb,'live'),
('language-bank:discipline_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Learning a language requires ____: a short study session every day is better than one long session at the weekend.","acceptedAnswers":["discipline"],"distractors":[{"text":"talent","reason":"Fits grammatically, but talent is natural ability, but the colon explains the habit of regular study."},{"text":"confidence","reason":"Fits grammatically, but confidence is feeling sure of yourself, but the colon explains the habit of regular study."},{"text":"memory","reason":"Fits grammatically, but memory is the ability to remember, but the colon explains the habit of regular study."}],"linkedVocabularyIds":["vocab_discipline"],"primaryEvidenceTargetId":"vocab_discipline","languageBankContextId":"discipline_ctx_5"}'::jsonb,'live'),
('language-bank:discipline_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Soldiers and athletes need ____ to follow orders and keep to the rules when conditions are hard.","acceptedAnswers":["discipline"],"distractors":[{"text":"fitness","reason":"Fits grammatically, but fitness is physical condition, not the self-control to follow rules when conditions are hard."},{"text":"imagination","reason":"Fits grammatically, but imagination is picturing new things, which does not help someone keep to the rules."},{"text":"experience","reason":"Fits grammatically, but experience is knowledge from the past, but the sentence is about self-control to keep to the rules."}],"linkedVocabularyIds":["vocab_discipline"],"primaryEvidenceTargetId":"vocab_discipline","languageBankContextId":"discipline_ctx_6"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The manager is ____: she cares less about how a task is done than about reaching the agreed result by Friday.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"detail-oriented","reason":"Fits grammatically, but detail-oriented means paying attention to small points, which contradicts caring less about how a task is done."},{"text":"team-oriented","reason":"Fits grammatically, but team-oriented means focused on the group, but the sentence is about reaching an agreed result."},{"text":"process-oriented","reason":"Fits grammatically, but process-oriented means focused on how a task is done, which is the opposite of the sentence."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_1"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"A ____ runner writes a target time for each race and trains only in ways that will help reach it.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"detail-oriented","reason":"Fits grammatically, but detail-oriented means paying attention to small points, but the sentence is about aiming for a target time."},{"text":"team-oriented","reason":"Fits grammatically, but team-oriented means focused on the group, but the sentence is about one runner’s target time."},{"text":"health-conscious","reason":"Fits grammatically, but health-conscious means caring about health, but the sentence is about reaching a target time."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_2"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Because she is so ____, she checks every month whether she is closer to the grades she has set herself.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"team-oriented","reason":"Fits grammatically, but team-oriented means focused on the group, but the sentence is about her own targets."},{"text":"people-oriented","reason":"Fits grammatically, but people-oriented means focused on other people, but the sentence is about her own targets."},{"text":"family-oriented","reason":"Fits grammatically, but family-oriented means focused on family life, but the sentence is about her own targets."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_3"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The coach wanted ____ players, who would keep their eyes on the final aim of promotion rather than on how enjoyable each session was.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"fun-loving","reason":"Fits grammatically, but fun-loving means enjoying having fun, which is the opposite of keeping eyes on the final aim."},{"text":"easy-going","reason":"Fits grammatically, but easy-going means relaxed, which does not fit keeping eyes on the final aim."},{"text":"sociable","reason":"Fits grammatically, but sociable means enjoying other people’s company, which does not describe focus on the final aim."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_4"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Our school is increasingly ____: every department sets yearly targets and reports on whether it has reached them.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"customer-oriented","reason":"Fits grammatically, but customer-oriented means focused on serving customers, but the sentence is about setting targets and reporting results."},{"text":"family-oriented","reason":"Fits grammatically, but family-oriented means focused on family life, but the sentence is about setting targets and reporting results."},{"text":"safety-oriented","reason":"Fits grammatically, but safety-oriented means focused on preventing harm, but the sentence is about setting targets and reporting results."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_5"}'::jsonb,'live'),
('language-bank:goal-oriented_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He was never ____: he drifted from one hobby to another without ever deciding what he wanted to achieve.","acceptedAnswers":["goal-oriented"],"distractors":[{"text":"team-oriented","reason":"Fits grammatically, but team-oriented means focused on the group, but the sentence is about not deciding what he wanted to achieve."},{"text":"detail-oriented","reason":"Fits grammatically, but detail-oriented means paying attention to small points, but the sentence is about not deciding what he wanted to achieve."},{"text":"safety-oriented","reason":"Fits grammatically, but safety-oriented means focused on preventing harm, but the sentence is about not deciding what he wanted to achieve."}],"linkedVocabularyIds":["vocab_goal_oriented"],"primaryEvidenceTargetId":"vocab_goal_oriented","languageBankContextId":"goal-oriented_ctx_6"}'::jsonb,'live'),
('language-bank:achievement_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Finishing the marathon in under four hours was a major ____ for someone who had only started running a year ago.","acceptedAnswers":["achievement"],"distractors":[{"text":"attempt","reason":"Fits grammatically, but an attempt is trying to do something, but finishing shows it was completed."},{"text":"routine","reason":"Fits grammatically, but a routine is something done regularly, but finishing in under four hours was special."},{"text":"celebration","reason":"Fits grammatically, but a celebration is a party, but the sentence describes what he did, not an event held afterwards."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_1"}'::jsonb,'live'),
('language-bank:achievement_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The coach called her place on the national team the most difficult ____ of her career, because no one from the school had ever done it before.","acceptedAnswers":["achievement"],"distractors":[{"text":"reward","reason":"Fits grammatically, but a reward is something given, but the coach is describing how hard it was to do."},{"text":"ambition","reason":"Fits grammatically, but an ambition is a hope for the future, but her place had already been won."},{"text":"decision","reason":"Fits grammatically, but a decision is a choice, but the coach is describing something no one from the school had ever done."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_2"}'::jsonb,'live'),
('language-bank:achievement_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The school celebrated the ____ of its students, who had won three national prizes in a single year.","acceptedAnswers":["achievement"],"distractors":[{"text":"mistake","reason":"Fits grammatically, but a mistake is an error, which does not fit celebrated and prizes."},{"text":"absence","reason":"Fits grammatically, but an absence is not being present, which does not fit celebrated and prizes."},{"text":"expectation","reason":"Fits grammatically, but an expectation is what people think will happen, but the school celebrated what the students had actually done."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_3"}'::jsonb,'live'),
('language-bank:achievement_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her proudest ____ was teaching herself to swim at the age of forty.","acceptedAnswers":["achievement"],"distractors":[{"text":"attempt","reason":"Fits grammatically, but an attempt is trying, but teaching herself to swim describes something she completed."},{"text":"hobby","reason":"Fits grammatically, but a hobby is an activity done for pleasure, but teaching herself to swim is described as something to be proud of."},{"text":"responsibility","reason":"Fits grammatically, but a responsibility is a duty, but the sentence describes something she did that she is proud of."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_4"}'::jsonb,'live'),
('language-bank:achievement_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"It was a great ____ for such a small club to reach the national final against much richer teams.","acceptedAnswers":["achievement"],"distractors":[{"text":"mistake","reason":"Fits grammatically, but a mistake contradicts great and reach the final."},{"text":"accident","reason":"Fits grammatically, but an accident is something unplanned and harmful, but the club earned its place in the final."},{"text":"embarrassment","reason":"Fits grammatically, but an embarrassment would be shameful, but reaching the final against richer teams is something to be proud of."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_5"}'::jsonb,'live'),
('language-bank:achievement_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Passing every exam with top grades was an ____ that his whole family was proud of.","acceptedAnswers":["achievement"],"distractors":[{"text":"expectation","reason":"Fits grammatically, but an expectation is something you think will happen, but the family was proud of what he did."},{"text":"obligation","reason":"Fits grammatically, but an obligation is a duty, but the family was proud of what he did."},{"text":"opportunity","reason":"Fits grammatically, but an opportunity is a chance, but the family was proud of what he actually did."}],"linkedVocabularyIds":["vocab_achievement"],"primaryEvidenceTargetId":"vocab_achievement","languageBankContextId":"achievement_ctx_6"}'::jsonb,'live'),
('language-bank:elite_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ squad is closed to all but the top one per cent of players in the country, chosen purely on results.","acceptedAnswers":["elite"],"distractors":[{"text":"open","reason":"Fits grammatically, but an open squad lets anyone join, but closed to all but the top one per cent says entry is limited."},{"text":"social","reason":"Fits grammatically, but a social squad plays for fun, but closed to all but the top one per cent and chosen purely on results says it is for the best."},{"text":"beginner","reason":"Fits grammatically, but a beginner squad is for new players, who cannot be among the top one per cent in the country."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_1"}'::jsonb,'live'),
('language-bank:elite_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Entry to the ____ competition is restricted to the top ten ranked players in the country, so most club players never qualify.","acceptedAnswers":["elite"],"distractors":[{"text":"open","reason":"Fits grammatically, but an open competition lets anyone enter, but restricted to the top ten ranked players says entry is limited."},{"text":"social","reason":"Fits grammatically, but a social competition is for fun, but restricted to the top ten ranked players says it is for the best."},{"text":"recreational","reason":"Fits grammatically, but a recreational competition is for enjoyment, but restricted to the top ten ranked players says it is for the best."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_2"}'::jsonb,'live'),
('language-bank:elite_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her coach said she had the ability to reach ____ level, which means competing against the best in the world.","acceptedAnswers":["elite"],"distractors":[{"text":"national","reason":"Fits grammatically, but national level means competing against the best in one country, but the sentence says the best in the world."},{"text":"regional","reason":"Fits grammatically, but regional level means competing against the best in one area, but the sentence says the best in the world."},{"text":"club","reason":"Fits grammatically, but club level means competing against other members of a club, but the sentence says the best in the world."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_3"}'::jsonb,'live'),
('language-bank:elite_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Scholarships are offered only to ____ sports people, meaning those who rank in the top one per cent nationally.","acceptedAnswers":["elite"],"distractors":[{"text":"average","reason":"Fits grammatically, but average sports people are in the middle of the range, but meaning those who rank in the top one per cent says the opposite."},{"text":"casual","reason":"Fits grammatically, but casual sports people play for fun, but meaning those who rank in the top one per cent says the opposite."},{"text":"ordinary","reason":"Fits grammatically, but ordinary sports people are not exceptional, but meaning those who rank in the top one per cent says the opposite."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_4"}'::jsonb,'live'),
('language-bank:elite_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Although he trains hard, he is still not good enough for the ____ squad, which only takes the very best players in the country.","acceptedAnswers":["elite"],"distractors":[{"text":"open","reason":"Fits grammatically, but an open squad takes anyone, but which only takes the very best players says the opposite."},{"text":"social","reason":"Fits grammatically, but a social squad plays for fun, but which only takes the very best players says the opposite."},{"text":"community","reason":"Fits grammatically, but a community squad is based on a local group, but which only takes the very best players in the country says the opposite."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_5"}'::jsonb,'live'),
('language-bank:elite_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Scouts say the ____ footballers they saw at the new academy are among the best fifty players of their age in the whole country.","acceptedAnswers":["elite"],"distractors":[{"text":"average","reason":"Fits grammatically, but average footballers are in the middle of the range, but among the best fifty in the whole country says the opposite."},{"text":"ordinary","reason":"Fits grammatically, but ordinary footballers are not exceptional, but among the best fifty in the whole country says the opposite."},{"text":"typical","reason":"Fits grammatically, but typical footballers are like most others, but among the best fifty in the whole country says the opposite."}],"linkedVocabularyIds":["vocab_elite"],"primaryEvidenceTargetId":"vocab_elite","languageBankContextId":"elite_ctx_6"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The support from the home crowd was so ____ that the young players could hardly think or hear their coach.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"half-hearted","reason":"Fits grammatically, but half-hearted support lacks energy, which contradicts the players hardly being able to think or hear their coach."},{"text":"gentle","reason":"Fits grammatically, but gentle support is soft and quiet, which contradicts the players hardly being able to think or hear their coach."},{"text":"unobtrusive","reason":"Fits grammatically, but unobtrusive support is quiet and easy to ignore, which contradicts the players hardly being able to think or hear their coach."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_1"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Voters gave the new mayor an ____ majority, with more than ninety per cent supporting her.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"insignificant","reason":"Fits grammatically, but an insignificant majority is tiny, but more than ninety per cent supporting her shows a huge one."},{"text":"unconvincing","reason":"Fits grammatically, but an unconvincing majority is too small to persuade, but more than ninety per cent supporting her shows a huge one."},{"text":"inadequate","reason":"Fits grammatically, but an inadequate majority is too small, but more than ninety per cent supporting her shows a huge one."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_2"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"After weeks of training, he felt an ____ sense of relief when the race was over, so strong that he cried at the finish line.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"ordinary","reason":"Fits grammatically, but an ordinary sense of relief is not unusually strong, which contradicts so strong that he cried."},{"text":"unnoticeable","reason":"Fits grammatically, but an unnoticeable sense of relief is too slight to be noticed, which contradicts so strong that he cried."},{"text":"understated","reason":"Fits grammatically, but an understated sense of relief is kept low-key, which contradicts so strong that he cried."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_3"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"There was ____ evidence that the player had broken the rules: the video, the witnesses and his own messages all agreed, and the committee had no doubt.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"inconclusive","reason":"Fits grammatically, but inconclusive evidence leaves the matter in doubt, which contradicts the committee had no doubt."},{"text":"conflicting","reason":"Fits grammatically, but conflicting evidence disagrees with itself, which contradicts the video, witnesses and messages all agreed."},{"text":"insufficient","reason":"Fits grammatically, but insufficient evidence is not enough to decide, which contradicts the committee had no doubt."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_4"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The amount of homework this week has been ____: it was so much that many students stopped trying to finish it all.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"manageable","reason":"Fits grammatically, but manageable means possible to cope with, but so much that many students stopped trying says the opposite."},{"text":"reasonable","reason":"Fits grammatically, but reasonable means fair, but so much that many students stopped trying says the opposite."},{"text":"unremarkable","reason":"Fits grammatically, but unremarkable means nothing special, but so much that many students stopped trying shows it was extreme."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_5"}'::jsonb,'live'),
('language-bank:overwhelming_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"An ____ response from fans, with so many messages that the staff could not read or answer them all, surprised the club.","acceptedAnswers":["overwhelming"],"distractors":[{"text":"underwhelming","reason":"Fits grammatically, but an underwhelming response is a disappointing one, which contradicts so many messages that the staff could not answer them all."},{"text":"insufficient","reason":"Fits grammatically, but an insufficient response is not enough, which contradicts so many messages that the staff could not answer them all."},{"text":"unenthusiastic","reason":"Fits grammatically, but an unenthusiastic response shows little interest, which contradicts so many messages that the staff could not answer them all."}],"linkedVocabularyIds":["vocab_overwhelming"],"primaryEvidenceTargetId":"vocab_overwhelming","languageBankContextId":"overwhelming_ctx_6"}'::jsonb,'live'),
('language-bank:generation_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"People born in the nineties are often described as part of the same ____, because they grew up with similar technology.","acceptedAnswers":["generation"],"distractors":[{"text":"family","reason":"Fits grammatically, but a family is made up of relatives, not people born in the same period."},{"text":"neighbourhood","reason":"Fits grammatically, but a neighbourhood is a place where people live, not a group defined by when they were born."},{"text":"school","reason":"Fits grammatically, but a school is a place of education, not a group defined by when they were born."}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation","languageBankContextId":"generation_ctx_1"}'::jsonb,'live'),
('language-bank:generation_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"A new ____ of players, all born after the year 2005, is replacing the champions who dominated the sport for years.","acceptedAnswers":["generation"],"distractors":[{"text":"season","reason":"Fits grammatically, but a season is part of the year, not a group of players born after 2005."},{"text":"century","reason":"Fits grammatically, but a century is one hundred years, not a group of players born after 2005."},{"text":"month","reason":"Fits grammatically, but a month is a period of about thirty days, not a group of players born after 2005."}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation","languageBankContextId":"generation_ctx_2"}'::jsonb,'live'),
('language-bank:generation_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Each ____ of people, born within a few years of each other, grows up with different music, technology and ideas about work.","acceptedAnswers":["generation"],"distractors":[{"text":"century","reason":"Fits grammatically, but a century is one hundred years, not a few years, and it is a period of time rather than a group of people."},{"text":"decade","reason":"Fits grammatically, but a decade is ten years, not a few years, and it is a period of time rather than a group of people."},{"text":"season","reason":"Fits grammatically, but a season is part of a year, and it is a period of time rather than a group of people."}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation","languageBankContextId":"generation_ctx_3"}'::jsonb,'live'),
('language-bank:generation_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Sports clubs hope that parents will pass their love of football to the next ____.","acceptedAnswers":["generation"],"distractors":[{"text":"season","reason":"Fits grammatically, but a season is part of the year, and love of football is passed to people, not to a season."},{"text":"family","reason":"Fits grammatically, but a family includes the parents themselves, but the love of football is passed to the people who come after them."},{"text":"neighbourhood","reason":"Fits grammatically, but a neighbourhood is a place where people live, not the group of people who come after the parents."}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation","languageBankContextId":"generation_ctx_4"}'::jsonb,'live'),
('language-bank:generation_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Anyone whose birth falls within the same fifteen years belongs to one ____ and often shares similar views about money and work.","acceptedAnswers":["generation"],"distractors":[{"text":"decade","reason":"Fits grammatically, but a decade is ten years, not fifteen, and it is a period of time rather than a group of people."},{"text":"family","reason":"Fits grammatically, but a family is made up of relatives, not people born in the same years."},{"text":"neighbourhood","reason":"Fits grammatically, but a neighbourhood is a place where people live, not a group defined by birth years."}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation","languageBankContextId":"generation_ctx_5"}'::jsonb,'live'),
('language-bank:generation_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The gap between grandparents and their grandchildren shows up in how each ____ spends its free time.","acceptedAnswers":["generation"],"distractors":[{"text":"neighbourhood","reason":"Fits grammatically, but a neighbourhood is a place, but the sentence contrasts two age groups."},{"text":"century","reason":"Fits grammatically, but a century is one hundred years, and it does not spend free time."},{"text":"team","reason":"Fits grammatically, but a team is a group that plays together, but the sentence contrasts grandparents with grandchildren."}],"linkedVocabularyIds":["vocab_generation"],"primaryEvidenceTargetId":"vocab_generation","languageBankContextId":"generation_ctx_6"}'::jsonb,'live'),
('language-bank:challenge_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The coach set the squad a ____: to run ten kilometres without stopping, to see who could push their limits.","acceptedAnswers":["challenge"],"distractors":[{"text":"schedule","reason":"Fits grammatically, but a schedule is a plan of times, but to see who could push their limits describes a difficult test."},{"text":"reward","reason":"Fits grammatically, but a reward is a prize, but to see who could push their limits describes a difficult test."},{"text":"deadline","reason":"Fits grammatically, but a deadline is a time limit, but to see who could push their limits describes a difficult test."}],"linkedVocabularyIds":["vocab_challenge"],"primaryEvidenceTargetId":"vocab_challenge","languageBankContextId":"challenge_ctx_1"}'::jsonb,'live'),
('language-bank:challenge_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Playing the champions away from home will be a serious ____ for our young team, but we are ready to try.","acceptedAnswers":["challenge"],"distractors":[{"text":"setback","reason":"Fits grammatically, but a setback is a problem that has already happened, but will be and ready to try describe something still to come."},{"text":"rival","reason":"Fits grammatically, but a rival is a person or team, not a difficulty a team is ready to try."},{"text":"embarrassment","reason":"Fits grammatically, but an embarrassment is a feeling after something has gone wrong, but will be and we are ready to try describe something still to come."}],"linkedVocabularyIds":["vocab_challenge"],"primaryEvidenceTargetId":"vocab_challenge","languageBankContextId":"challenge_ctx_2"}'::jsonb,'live'),
('language-bank:challenge_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Adults learning an instrument face a real ____ in staying patient when progress feels slow.","acceptedAnswers":["challenge"],"distractors":[{"text":"hobby","reason":"Fits grammatically, but a hobby is an activity chosen for pleasure, not a difficulty that adults face."},{"text":"habit","reason":"Fits grammatically, but a habit is something done regularly, not a difficulty that adults face."},{"text":"privilege","reason":"Fits grammatically, but a privilege is a special advantage, not a difficulty that adults face."}],"linkedVocabularyIds":["vocab_challenge"],"primaryEvidenceTargetId":"vocab_challenge","languageBankContextId":"challenge_ctx_3"}'::jsonb,'live'),
('language-bank:challenge_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Running a marathon for charity is a ____ for most people, because they have never run more than a few kilometres before.","acceptedAnswers":["challenge"],"distractors":[{"text":"routine","reason":"Fits grammatically, but a routine is a regular set of actions, which does not fit people who have never run more than a few kilometres."},{"text":"custom","reason":"Fits grammatically, but a custom is a traditional way of behaving, which does not fit people who have never run more than a few kilometres."},{"text":"ritual","reason":"Fits grammatically, but a ritual is a fixed ceremony, which does not fit people who have never run more than a few kilometres."}],"linkedVocabularyIds":["vocab_challenge"],"primaryEvidenceTargetId":"vocab_challenge","languageBankContextId":"challenge_ctx_4"}'::jsonb,'live'),
('language-bank:challenge_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Finding enough time for training while studying full-time is the biggest ____ for most athletes at university.","acceptedAnswers":["challenge"],"distractors":[{"text":"expense","reason":"Fits grammatically, but an expense is a cost, but finding enough time is about difficulty, not money."},{"text":"distraction","reason":"Fits grammatically, but a distraction takes attention away from something, but finding enough time is about how hard the whole situation is."},{"text":"reason","reason":"Fits grammatically, but a reason explains why something happens, but the sentence describes the hardest thing they face."}],"linkedVocabularyIds":["vocab_challenge"],"primaryEvidenceTargetId":"vocab_challenge","languageBankContextId":"challenge_ctx_5"}'::jsonb,'live'),
('language-bank:challenge_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The new course is a ____ even for experienced players: every exercise tests a different skill.","acceptedAnswers":["challenge"],"distractors":[{"text":"formality","reason":"Fits grammatically, but a formality is a step that is easy and expected, but every exercise tests a different skill."},{"text":"breeze","reason":"Fits grammatically, but a breeze is something very easy, but every exercise tests a different skill."},{"text":"relief","reason":"Fits grammatically, but a relief is the end of a worry, but every exercise tests a different skill."}],"linkedVocabularyIds":["vocab_challenge"],"primaryEvidenceTargetId":"vocab_challenge","languageBankContextId":"challenge_ctx_6"}'::jsonb,'live'),
('language-bank:solution_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The club finally found a ____ that ended the shortage of training space: it shared the school gym.","acceptedAnswers":["solution"],"distractors":[{"text":"complaint","reason":"Fits grammatically, but a complaint is an expression of dissatisfaction, which does not end a shortage."},{"text":"delay","reason":"Fits grammatically, but a delay is a late arrival, which does not end a shortage."},{"text":"rumour","reason":"Fits grammatically, but a rumour is an unproved story, which does not end a shortage."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_1"}'::jsonb,'live'),
('language-bank:solution_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"One practical ____ to the noise problem is to move the matches to the afternoon.","acceptedAnswers":["solution"],"distractors":[{"text":"obstacle","reason":"Fits grammatically, but an obstacle makes a problem harder, but to move the matches describes a way of ending the noise."},{"text":"threat","reason":"Fits grammatically, but a threat is a danger, but to move the matches describes a way of ending the noise."},{"text":"cause","reason":"Fits grammatically, but a cause is what creates a problem, but to move the matches describes a way of ending the noise."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_2"}'::jsonb,'live'),
('language-bank:solution_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"There is no simple ____ to the problem of injuries among young athletes, but good coaching helps.","acceptedAnswers":["solution"],"distractors":[{"text":"definition","reason":"Fits grammatically, but a definition says what a word means, but good coaching helps describes a way of reducing the problem."},{"text":"prediction","reason":"Fits grammatically, but a prediction says what will happen, but good coaching helps describes a way of reducing the problem."},{"text":"excuse","reason":"Fits grammatically, but an excuse defends a failure, but good coaching helps describes a way of reducing the problem."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_3"}'::jsonb,'live'),
('language-bank:solution_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The mechanic said there was no easy ____ to the engine fault: the whole part would have to be replaced.","acceptedAnswers":["solution"],"distractors":[{"text":"objection","reason":"Fits grammatically, but an objection is a complaint, but the whole part would have to be replaced describes a way of dealing with the fault."},{"text":"warning","reason":"Fits grammatically, but a warning tells people about danger, but the whole part would have to be replaced describes a way of dealing with the fault."},{"text":"threat","reason":"Fits grammatically, but a threat is a danger, but the whole part would have to be replaced describes a way of dealing with the fault."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_4"}'::jsonb,'live'),
('language-bank:solution_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The puzzle was finally finished when the students found the ____ that explained all of the clues.","acceptedAnswers":["solution"],"distractors":[{"text":"clue","reason":"Fits grammatically, but a clue is one of the pieces of information, but it cannot be the thing that explains all of the clues."},{"text":"hint","reason":"Fits grammatically, but a hint is a small piece of help, but it cannot be the thing that explains all of the clues."},{"text":"question","reason":"Fits grammatically, but a question is what must be answered, not the answer that explains all of the clues."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_5"}'::jsonb,'live'),
('language-bank:solution_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Sharing equipment turned out to be a cheap ____ to the club''s money problem, since no new balls had to be bought.","acceptedAnswers":["solution"],"distractors":[{"text":"penalty","reason":"Fits grammatically, but a penalty is a punishment, which does not describe a way of ending a money problem."},{"text":"symptom","reason":"Fits grammatically, but a symptom is a sign of a problem, not a way of ending it."},{"text":"nuisance","reason":"Fits grammatically, but a nuisance is an annoyance, which does not describe a way of ending a money problem."}],"linkedVocabularyIds":["vocab_solution"],"primaryEvidenceTargetId":"vocab_solution","languageBankContextId":"solution_ctx_6"}'::jsonb,'live'),
('language-bank:pastime_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Collecting old coins is a popular ____ among retired people, who enjoy it in the afternoons.","acceptedAnswers":["pastime"],"distractors":[{"text":"profession","reason":"Fits grammatically, but a profession is a job, but who enjoy it in the afternoons describes something done for pleasure."},{"text":"duty","reason":"Fits grammatically, but a duty is something you must do, but who enjoy it describes something done for pleasure."},{"text":"sport","reason":"Fits grammatically, but a sport is a physical competitive activity, but collecting coins is not."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_1"}'::jsonb,'live'),
('language-bank:pastime_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"For many teenagers, playing video games is a favourite ____, not a way of earning money.","acceptedAnswers":["pastime"],"distractors":[{"text":"job","reason":"Fits grammatically, but a job is work done for money, which the sentence rules out with not a way of earning money."},{"text":"subject","reason":"Fits grammatically, but a subject is something studied at school, not something done for enjoyment."},{"text":"lesson","reason":"Fits grammatically, but a lesson is a period of teaching, not something done for enjoyment."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_2"}'::jsonb,'live'),
('language-bank:pastime_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Cricket began as a village ____, played on summer evenings for fun, before it became a professional sport.","acceptedAnswers":["pastime"],"distractors":[{"text":"business","reason":"Fits grammatically, but a business is run to earn money, but played on summer evenings for fun describes an activity enjoyed."},{"text":"duty","reason":"Fits grammatically, but a duty is something you must do, but for fun describes an activity enjoyed."},{"text":"profession","reason":"Fits grammatically, but a profession is a job, but for fun and before it became a professional sport rule it out."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_3"}'::jsonb,'live'),
('language-bank:pastime_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her favourite ____ is walking in the hills on Sunday mornings, when she has no homework.","acceptedAnswers":["pastime"],"distractors":[{"text":"subject","reason":"Fits grammatically, but a subject is something studied at school, but she has no homework shows this is free-time enjoyment."},{"text":"lesson","reason":"Fits grammatically, but a lesson is a period of teaching, but she has no homework shows this is free-time enjoyment."},{"text":"task","reason":"Fits grammatically, but a task is a piece of work, but she has no homework shows this is free-time enjoyment."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_4"}'::jsonb,'live'),
('language-bank:pastime_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Not everyone sees fishing as an exciting ____, but millions of people enjoy it as a relaxing activity every week.","acceptedAnswers":["pastime"],"distractors":[{"text":"subject","reason":"Fits grammatically, but a subject is something studied at school, but millions of people enjoy it as a relaxing activity."},{"text":"lesson","reason":"Fits grammatically, but a lesson is a period of teaching, but millions of people enjoy it as a relaxing activity."},{"text":"season","reason":"Fits grammatically, but a season is part of the year, not an activity people do every week."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_5"}'::jsonb,'live'),
('language-bank:pastime_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Many parents want their children to find a ____ for their free time that is not connected to screens, such as painting or gardening.","acceptedAnswers":["pastime"],"distractors":[{"text":"career","reason":"Fits grammatically, but a career is a long-term job, but for their free time says the activity is for enjoyment."},{"text":"subject","reason":"Fits grammatically, but a subject is studied at school, but for their free time says the activity is for enjoyment."},{"text":"profession","reason":"Fits grammatically, but a profession is a job, but for their free time says the activity is for enjoyment."}],"linkedVocabularyIds":["vocab_pastime"],"primaryEvidenceTargetId":"vocab_pastime","languageBankContextId":"pastime_ctx_6"}'::jsonb,'live'),
('language-bank:feat_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"After two years of daily training, she completed the mountain run in under an hour, a ____ that she had earned through practice rather than chance.","acceptedAnswers":["feat"],"distractors":[{"text":"fluke","reason":"Fits grammatically, but a fluke is an accident, which contradicts earned through practice rather than chance."},{"text":"coincidence","reason":"Fits grammatically, but a coincidence happens by chance, which contradicts earned through practice rather than chance."},{"text":"gift","reason":"Fits grammatically, but a gift is something given, which contradicts earned through practice."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_1"}'::jsonb,'live'),
('language-bank:feat_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Finishing the race with a broken ankle was a ____ that earned the runner a standing ovation from the whole stadium.","acceptedAnswers":["feat"],"distractors":[{"text":"flop","reason":"Fits grammatically, but a flop is a failure, which does not earn a standing ovation."},{"text":"blunder","reason":"Fits grammatically, but a blunder is a serious mistake, which does not earn a standing ovation."},{"text":"mistake","reason":"Fits grammatically, but a mistake is an error, which does not earn a standing ovation."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_2"}'::jsonb,'live'),
('language-bank:feat_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Walking a tightrope between two skyscrapers was a ____ that left the whole crowd speechless with admiration.","acceptedAnswers":["feat"],"distractors":[{"text":"fear","reason":"Fits grammatically, but fear is a feeling the walker has, not something that leaves a crowd speechless with admiration."},{"text":"threat","reason":"Fits grammatically, but a threat is a danger, which does not cause speechless admiration."},{"text":"scandal","reason":"Fits grammatically, but a scandal causes shock and blame, not admiration."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_3"}'::jsonb,'live'),
('language-bank:feat_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Reaching the summit in under five hours after only two months of training was a ____ that surprised even her coach.","acceptedAnswers":["feat"],"distractors":[{"text":"habit","reason":"Fits grammatically, but a habit is something done repeatedly, but reaching the summit once is a single achievement."},{"text":"custom","reason":"Fits grammatically, but a custom is a traditional way of behaving, but reaching the summit once is a single achievement."},{"text":"routine","reason":"Fits grammatically, but a routine is a regular set of actions, but reaching the summit once is a single achievement."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_4"}'::jsonb,'live'),
('language-bank:feat_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Fixing the damaged roof in a single weekend was a remarkable ____, and the volunteers did it all for free.","acceptedAnswers":["feat"],"distractors":[{"text":"fee","reason":"Fits grammatically, but a fee is a payment, which contradicts the volunteers did it all for free."},{"text":"price","reason":"Fits grammatically, but a price is an amount paid, which contradicts the volunteers did it all for free."},{"text":"charge","reason":"Fits grammatically, but a charge is an amount asked for payment, which contradicts the volunteers did it all for free."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_5"}'::jsonb,'live'),
('language-bank:feat_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Arranging a trip for three hundred students in one afternoon was quite a ____, and the teachers still talk about how smoothly it went.","acceptedAnswers":["feat"],"distractors":[{"text":"mess","reason":"Fits grammatically, but a mess is a badly handled situation, which contradicts how smoothly it went."},{"text":"muddle","reason":"Fits grammatically, but a muddle is a confused situation, which contradicts how smoothly it went."},{"text":"shambles","reason":"Fits grammatically, but a shambles is a disorganised failure, which contradicts how smoothly it went."}],"linkedVocabularyIds":["vocab_feat"],"primaryEvidenceTargetId":"vocab_feat","languageBankContextId":"feat_ctx_6"}'::jsonb,'live'),
('language-bank:regardless_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The match will take place ____ of the weather, so bring waterproof clothes just in case.","acceptedAnswers":["regardless"],"distractors":[{"text":"instead","reason":"Fits grammatically, but instead of the weather would mean the weather replaces the match, which does not fit bring waterproof clothes just in case."},{"text":"because","reason":"Fits grammatically, but because of the weather would mean the weather causes the match, which does not fit bring waterproof clothes just in case."},{"text":"irrelevant","reason":"Fits grammatically, but irrelevant of is not used in this pattern; the standard phrase is irrespective of or regardless of."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_1"}'::jsonb,'live'),
('language-bank:regardless_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Every student must attend training, ____ of their ability or experience, so beginners and the best players train together.","acceptedAnswers":["regardless"],"distractors":[{"text":"because","reason":"Fits grammatically, but because of their ability would make ability the reason, but beginners and the best players train together shows it makes no difference."},{"text":"unaffected","reason":"Fits grammatically, but unaffected of is not used in this pattern; the standard phrase is regardless of."},{"text":"out","reason":"Fits grammatically, but out of their ability does not fit beginners and the best players training together."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_2"}'::jsonb,'live'),
('language-bank:regardless_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Their best striker was injured, which was a good reason to stop, but the team carried on with the final ____ of the injury.","acceptedAnswers":["regardless"],"distractors":[{"text":"ahead","reason":"Fits grammatically, but ahead of the injury would mean before it happened, but the striker was already injured."},{"text":"because","reason":"Fits grammatically, but because of the injury would make it the reason for carrying on, but the sentence calls it a good reason to stop."},{"text":"irrelevant","reason":"Fits grammatically, but irrelevant of is not used in this pattern; the standard phrase is regardless of."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_3"}'::jsonb,'live'),
('language-bank:regardless_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The school offers a free place to every applicant, ____ of family income, so rich and poor families are treated the same.","acceptedAnswers":["regardless"],"distractors":[{"text":"because","reason":"Fits grammatically, but because of family income would make income the reason, but rich and poor families are treated the same."},{"text":"instead","reason":"Fits grammatically, but instead of family income would mean income replaces something, but the sentence says rich and poor are treated the same."},{"text":"out","reason":"Fits grammatically, but out of family income does not fit the idea that income does not matter."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_4"}'::jsonb,'live'),
('language-bank:regardless_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"You must submit the report by Friday, ____ of whether you have finished the final section.","acceptedAnswers":["regardless"],"distractors":[{"text":"because","reason":"Fits grammatically, but because of whether you have finished would give a reason, whereas the sentence says it does not matter."},{"text":"instead","reason":"Fits grammatically, but instead of whether you have finished does not fit the idea that it does not matter."},{"text":"unaffected","reason":"Fits grammatically, but unaffected of is not used in this pattern; the standard phrase is regardless of."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_5"}'::jsonb,'live'),
('language-bank:regardless_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"He kept running, ____ of the pain in his knee and the cheers telling him to stop.","acceptedAnswers":["regardless"],"distractors":[{"text":"because","reason":"Fits grammatically, but because of the pain would make it the reason to keep running, but the cheers telling him to stop show he ignored them."},{"text":"in","reason":"Fits grammatically, but in of the pain is not a phrase; the standard phrase is regardless of."},{"text":"instead","reason":"Fits grammatically, but instead of the pain does not fit the idea of ignoring pain and cheers."}],"linkedVocabularyIds":["vocab_regardless"],"primaryEvidenceTargetId":"vocab_regardless","languageBankContextId":"regardless_ctx_6"}'::jsonb,'live'),
('language-bank:monetary_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The trophy has little ____ value, but it means a great deal to the winners.","acceptedAnswers":["monetary"],"distractors":[{"text":"momentary","reason":"Fits grammatically, but momentary means lasting a very short time, but value in this sentence is contrasted with what it means to the winners."},{"text":"military","reason":"Fits grammatically, but military relates to armed forces, which does not fit value of a trophy."},{"text":"monthly","reason":"Fits grammatically, but monthly means happening every month, which does not fit value of a trophy."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_1"}'::jsonb,'live'),
('language-bank:monetary_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Volunteers receive no ____ reward for helping at the tournament, only a free t-shirt.","acceptedAnswers":["monetary"],"distractors":[{"text":"mandatory","reason":"Fits grammatically, but mandatory means compulsory, which does not describe a reward."},{"text":"momentary","reason":"Fits grammatically, but momentary means lasting a very short time, which does not describe the kind of reward."},{"text":"material","reason":"Fits grammatically, but material would include a t-shirt, which the sentence says is the only thing they receive."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_2"}'::jsonb,'live'),
('language-bank:monetary_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The club offered ____ support, giving each student a small payment toward travel costs.","acceptedAnswers":["monetary"],"distractors":[{"text":"moral","reason":"Fits grammatically, but moral support is encouragement, but giving each student a small payment is financial."},{"text":"military","reason":"Fits grammatically, but military relates to armed forces, which does not fit a small payment toward travel costs."},{"text":"momentary","reason":"Fits grammatically, but momentary means lasting a very short time, which does not describe a payment."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_3"}'::jsonb,'live'),
('language-bank:monetary_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Some prizes are ____: winners receive £10,000 in cash to spend as they choose, while medals and cups have no exchangeable financial value.","acceptedAnswers":["monetary"],"distractors":[{"text":"mandatory","reason":"Fits grammatically, but mandatory means compulsory, which does not describe £10,000 in cash."},{"text":"ceremonial","reason":"Fits grammatically, but ceremonial prizes are given for show, but £10,000 to spend as winners choose has substantial financial value."},{"text":"symbolic","reason":"Fits grammatically, but symbolic prizes only stand for something, but £10,000 to spend as winners choose has substantial financial value."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_4"}'::jsonb,'live'),
('language-bank:monetary_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The study found that happiness depends only partly on ____ gain, such as a higher salary or a lottery win; friends and health matter more.","acceptedAnswers":["monetary"],"distractors":[{"text":"momentary","reason":"Fits grammatically, but momentary means lasting a very short time, which does not describe a higher salary or a lottery win."},{"text":"moral","reason":"Fits grammatically, but moral relates to right and wrong, which does not describe a higher salary or a lottery win."},{"text":"mental","reason":"Fits grammatically, but mental relates to the mind, which does not describe a higher salary or a lottery win."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_5"}'::jsonb,'live'),
('language-bank:monetary_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The high ____ cost of the stadium, nearly two hundred million pounds, made the council decide to share it with a neighbouring town.","acceptedAnswers":["monetary"],"distractors":[{"text":"moral","reason":"Fits grammatically, but moral relates to right and wrong, which does not describe a cost of nearly two hundred million pounds."},{"text":"mental","reason":"Fits grammatically, but mental relates to the mind, which does not describe a cost of nearly two hundred million pounds."},{"text":"mandatory","reason":"Fits grammatically, but mandatory means compulsory, which does not describe a cost of nearly two hundred million pounds."}],"linkedVocabularyIds":["vocab_monetary"],"primaryEvidenceTargetId":"vocab_monetary","languageBankContextId":"monetary_ctx_6"}'::jsonb,'live'),
('language-bank:estimated_ctx_1',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ crowd at the final was fifty thousand, though officials admitted that nobody had counted exactly.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts nobody had counted exactly."},{"text":"confirmed","reason":"Fits grammatically, but confirmed means checked and certain, which contradicts nobody had counted exactly."},{"text":"registered","reason":"Fits grammatically, but registered would mean recorded one by one, which contradicts nobody had counted exactly."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_1"}'::jsonb,'live'),
('language-bank:estimated_ctx_2',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ cost of the new stadium is two hundred million pounds, but the final bill may be higher.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts the final bill may be higher."},{"text":"actual","reason":"Fits grammatically, but actual means the real figure, but the final bill may be higher shows this figure is not final."},{"text":"guaranteed","reason":"Fits grammatically, but guaranteed means promised, which contradicts the final bill may be higher."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_2"}'::jsonb,'live'),
('language-bank:estimated_ctx_3',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ figure of about three thousand visitors a day was published by officials, though nobody knew the true number.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts nobody knew the true number."},{"text":"confirmed","reason":"Fits grammatically, but confirmed means proved to be true, which contradicts nobody knew the true number."},{"text":"counted","reason":"Fits grammatically, but a counted figure comes from counting every visitor, which contradicts nobody knew the true number."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_3"}'::jsonb,'live'),
('language-bank:estimated_ctx_4',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"The ____ distance of the race is ten kilometres, but the course has not yet been measured.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts the course has not yet been measured."},{"text":"measured","reason":"Fits grammatically, but measured contradicts the course has not yet been measured."},{"text":"certified","reason":"Fits grammatically, but certified means officially checked and confirmed, which contradicts the course has not yet been measured."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_4"}'::jsonb,'live'),
('language-bank:estimated_ctx_5',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Because the exact date cannot be known, scientists can only give ____ ages for the fossil.","acceptedAnswers":["estimated"],"distractors":[{"text":"exact","reason":"Fits grammatically, but exact contradicts the exact date cannot be known."},{"text":"precise","reason":"Fits grammatically, but precise means exact, which contradicts the exact date cannot be known."},{"text":"pinpoint","reason":"Fits grammatically, but pinpoint means exact to a particular point, which contradicts the exact date cannot be known."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_5"}'::jsonb,'live'),
('language-bank:estimated_ctx_6',1,'writing_set','{"taskType":"language_bank_context","prompt":"Complete the sentence with the best word or phrase.","sourceText":"Her ____ finishing time is two hours, but it depends on the weather on the day.","acceptedAnswers":["estimated"],"distractors":[{"text":"final","reason":"Fits grammatically, but final means no longer able to change, but it depends on the weather shows it can change."},{"text":"confirmed","reason":"Fits grammatically, but confirmed means checked and certain, but it depends on the weather shows it is only a guess."},{"text":"recorded","reason":"Fits grammatically, but recorded means already measured, but it depends on the weather shows it has not happened yet."}],"linkedVocabularyIds":["vocab_estimated"],"primaryEvidenceTargetId":"vocab_estimated","languageBankContextId":"estimated_ctx_6"}'::jsonb,'live')
